                    if (dmlService.J_IsRecordExist("MST_BOOKMARK_DETAIL", strQuery) == true)
                    {
                        //intAsstId = TdsMan.T_GetBookMarkDetail(T_TransactionMode.SHOW.ToString(), 0, "", strFormNo, 0, TDSMAN.Classes.TDSMAN.T_MACHINE_ID, out strQuarter, out strCompanyName);
                        intAsstId = TdsMan.T_GetBookMarkDetail(T_TransactionMode.SHOW.ToString(), 0, "", strFormNo, 0, TDSMAN.Classes.TDSMAN.T_MACHINE_ID, out strQuarter, out strCompanyName, out strCompanyTAN);
                        strSQL = @"SELECT FA_YEAR
