                        cmbFinancialYear.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));//Convert.ToInt32(Support.SetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex, intAsstId));
                        cmbQuarter.Text = strQuarter;
                        //cmbCompany.Text = strCompanyName ; //-- 2024/10/23
                        cmbCompany.Text = strCompanyName + " [" + strCompanyTAN + "]";
                    }
                }
                //----------------------------------------------------------
                //ADDED BY DHRUB ON 13/01/2014 FOR DEDUCTED DATE VISIBILITY 
                //----------------------------------------------------------
                //TdsMan.GetSetup();
                //------------------
                //if (TDSMAN.Classes.TDSMAN.T_ShowCompanyWiseDeductee == true)
                //    lstDeducteeHelp.BackColor = Color.LightBlue;
                //else
                //    lstDeducteeHelp.BackColor = Color.MistyRose;
                //if (OrphanEntry == 1)
                //{
                //    LoadDeducteeFirstModuleDesign();
                //    //
                //    return;
                //}
                if (OrphanEntry == T_DEDUCTEE_FIRST_MODULES.DEDUCTEE) //-- 2014/12/12
                {
                    //--
                    lblTitle.Text = lblTitle.Text + " - Deductee entry without Challan";
                    lblTitle.BackColor = Color.Blue;
                    lblTitle.ForeColor = Color.White;
                    //--
                    //////btnChallanDeducteeEntry.Location = new Point(615, btnChallanDeducteeEntry.Location.Y);
                    btnChallanDeducteeEntry.Text = Tabbed_Mode.DeducteeFirst;
                    //btnChallanDeducteeEntry.Height = 23;
