                    //
                    //BtnDelete.Visible = true;
                    //BtnDelete.Enabled = true;
                    //BtnDelete.BackColor = Color.Lavender;
                    //--
                    grpControlSummary.Visible = false;
                    grpDeducteeRecords.Visible = true;
                    grpOrphanWarningMessage.Visible = true;
                    lblWarningMessageOrphan.Text = "Returns cannot be generated if there are Untagged Deductee records.";
                    //--
                    if (strFormNo == T_FormNo.F24Q)
                        BtnDelete.Text = "Tag Employee(s)";
                    else
                        BtnDelete.Text = "Tag Deductee(s)";
                    //--
                    //////BtnDelete.Location = new Point(787, btnChallanDeducteeEntry.Location.Y);
                    BtnDelete.Width = 122;
                    //
                    grpLastProvisionalReceiptNo.Visible = false;
                    grpAddressChange.Visible = false;
                    grpReturnFilingStatus.Visible = false;
                    //--
                    lblSelectReturn.Visible = true;
                    lblEnterChallan.Visible = true;
                    lblEnterDeductee.Visible = true;
                    lblEnterChallan.Text = "Enter Deductee";
                    lblEnterDeductee.Text = "Tag Deductee";
                    lblGenerateReturns.Visible = false;
                    lblArrow1.Visible = true;
                    lblArrow2.Visible = true;
                    lblArrow2.Width = 40;
                    lblArrow2.Location = new Point(470, lblArrow2.Location.Y);
                    lblArrow2.Text = "OR";
                    lblArrow2.Image = null;
                    lblArrow3.Visible = false;
                    //--
                }
                //else if (OrphanEntry == T_DEDUCTEE_FIRST_MODULES.CHALLAN) //-- 2014/12/12
                //{
                //    btnChallanDeducteeEntry.Text = Tabbed_Mode.Challan;
                //    //
                //    BtnCancel.Enabled = false;
                //    BtnCancel.BackColor = Color.LightGray;
                //    //
                //    grpLastProvisionalReceiptNo.Enabled = false;
                //    grpAddressChange.Enabled = false;
                //}
                //-- Added By Abhishek Dey On 18/04/2018 --
                if (strFormNo != T_FormNo.F24Q)
                {
                    lblEmpRefNo.Visible = false;
                    txtEmpRefNo.Visible = false;
