                        cmbDeducteeCode.Visible = false;
                    }
                    else
                    {
                        lblCode.Visible = true;
                        cmbDeducteeCode.Visible = true;
                    }
                    //-- ANIK @ 2020/07/27
                    if (strFormNo == T_FormNo.F26Q && TDSMAN.Classes.TDSMAN.T_ShareReferenceNoF26Q == true)
                    {
                        //lblEmpRefNo.Visible = true;
