                    }
                    else
                    {
                        lblEmpRefNo.Visible = false;
                        txtEmpRefNo.Visible = false;
                    }
                    //--
                    if (strFormNo == T_FormNo.F27Q && TDSMAN.Classes.TDSMAN.T_ShareReferenceNoF27Q == true)
                    {
                        //lblEmpRefNo.Visible = true;
                        //txtEmpRefNo.Visible = true;
