                    }
                    //-- ANIK @ 2023/09/11
                    if (strFormNo == T_FormNo.F27EQ && TDSMAN.Classes.TDSMAN.T_ShareReferenceNoF27EQ == true)
                    {
                        //lblEmpRefNo.Visible = true;
