        #region BtnCancel_Click
        private void BtnCancel_Click(object sender, System.EventArgs e)
        {
            try
            {
                //-- Added By Abhishek dey On 31/10/2019 --
                #region IS COMPANY ACCESSIBLE FOR CLIENT
                if (TDSMAN.Classes.TDSMAN.T_ClientServerMachine == T_CLIENT_SERVER_MACHINE.CLIENT_MACHINE)
                {
                    if (dmlService.J_IsDatabaseObjectExist("TRN_TAN_USER") == true)
                    {
                        if (TdsMan.IsCompanyAccessible(Convert.ToInt64(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)), TDSMAN.Classes.TDSMAN.T_MACHINE_ID) == false)
                        {
                            cmnService.J_UserMessage("You are not authorised to proceed");
                            BtnCancel.Select();
                            return;
                        }
                        //if (Convert.ToInt32(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(*) FROM TRN_TAN_USER WHERE SETUP_ID = " + TDSMAN.Classes.TDSMAN.T_MACHINE_ID + " AND COMPANY_ID = " + )) > 0)

                    }
                }
                #endregion
                //-----------------------------------------
                #region GenerateBasicInfoId - Indrajit on 23-02-2013
                //Added by Indrajit on 23-02-2013 to add the basic information
                //-----------------------------------------------------------
                if (lngBasicInfoID == 0)
                {
                    dmlService.J_BeginTransaction();

                    if (TdsMan.T_GenerateBasicInfoId(dmlService.J_pCommand, Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)),
                                            cmbQuarter.Text,
                                            Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)),
                                            strFormNo) == true)
                    {
                        strSQL = "SELECT COUNT(*) " +
                            "     FROM   TRN_BASIC_INFO " +
                            "     WHERE  ASST_ID     = " + Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)) +
                            "     AND    QTR         ='" + cmbQuarter.Text + "'" +
                            "     AND    COMPANY_ID  = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) +
                            "     AND    FORM_NO     ='" + cmnService.J_ReplaceQuote(strFormNo) + "'";
                        //--
                        if (cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(dmlService.J_pCommand, strSQL)) > 1)
                        {
                            //cmnService.J_UserMessage("This header entry exists");
                            dmlService.J_Rollback();
                        }
                        else
                        {
                            //-----------------------------------------------
                            lngBasicInfoID = TdsMan.T_ReturnBasicInfoId(dmlService.J_pCommand, Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)),
                                                cmbQuarter.Text,
                                                Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)),
                                                strFormNo);
                            //-----------------------------------------------
                            InsertCompanyBasicInfo(Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)), lngBasicInfoID);
                            dmlService.J_Commit();
                        }
                    }
                    else
                        dmlService.J_Rollback();
                }
                #endregion
                //-----------------------------------------------------------
                //Added by Indrajit on 22-02-2013 to incorporate Basic Info locking
                #region INCORPORATE_BASIC_INFO_LOCKING

                TDSMAN.Classes.TDSMAN.T_pBasicInfoId = lngBasicInfoID;
                //================================================
                if (TDSMAN.Classes.TDSMAN.T_PackageType == T_PACKAGE_TYPE.MULTI_USER)
                {
                    if (TdsMan.LockBasicInfoEntry(strFormNo) == false)
                    {
                        BtnExit.Select();
                        return;
                    }
                }
                #endregion

                if (lblSearchMode.Text == Tabbed_Mode.Basic)
                {
                    //cmnService.J_UserMessage("FVU still awaited... \nReturn Generation for Tax Year 2026-27 is currently on hold.");
                    //return;
                    //Added by Dhrub On 08/11/2013 For BookMark
                    //---------------------------------------------------
                    if (TDSMAN.Classes.TDSMAN.T_pBookMarkOption == true)
                    {
                        //strQuery = @"FORM_NAME= '" + strFormNo + "' ";
                        //-- 2014/11/14
                        strQuery = @" FORM_NAME= '" + strFormNo + "' AND SETUPID = " + TDSMAN.Classes.TDSMAN.T_MACHINE_ID;
                        if (dmlService.J_IsRecordExist("MST_BOOKMARK_DETAIL", strQuery) == true)
                        {
                            //Update the Form BookMarkDetail [T_TransactionMode.UPDATE]
                            intAsstId = TdsMan.T_GetBookMarkDetail(T_TransactionMode.UPDATE.ToString(),
                                                                Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)),
                                                                cmbQuarter.Text,
                                                                strFormNo,
                                                                Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)),
                                                                TDSMAN.Classes.TDSMAN.T_MACHINE_ID,
                                                                out strQuarter,
                                                                out strCompanyName
                                                               );
                        }
                        else
                        {
                            //Inserting the Form BookMarkDetail [T_TransactionMode.INSERT]
                            intAsstId = TdsMan.T_GetBookMarkDetail(T_TransactionMode.INSERT.ToString(),
                                                                Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)),
                                                                cmbQuarter.Text,
                                                                strFormNo,
                                                                Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)),
                                                                TDSMAN.Classes.TDSMAN.T_MACHINE_ID,
                                                                out strQuarter,
                                                                out strCompanyName
                                                               );
                        }
                    }
                    //---------------------------------------------------
                    if (TDSMAN.Classes.TDSMAN.T_pVersionType == T_VERSION_TYPE.TRIAL_VERSION)
                    {
                        ////if (cmbQuarter.Text == T_Qtr.Q4)
                        ////{
                        ////    TrnTrialMessageBox TrialMessageBox = new TrnTrialMessageBox();
                        ////    TrialMessageBox.StartPosition = FormStartPosition.CenterScreen;
                        ////    TrialMessageBox.lblMessage2.Text = "Return cannot be generated for Qtr 4 in Trial Version";
                        ////    TrialMessageBox.Show();
                        ////    return;
                        ////}
                        //--####################
                        if (TdsMan.AllowTrialReturn(lngBasicInfoID) == false)
                        {
                            TrnTrialMessageBox TrialMessageBox = new TrnTrialMessageBox();
                            TrialMessageBox.StartPosition = FormStartPosition.CenterScreen;
                            //TrialMessageBox.lblMessage2.Text = "Return cannot be generated as the trial version supports only " + TDSMAN.Classes.TDSMAN.T_pMaxDeducteeDetailsCount + " nos. of deductee records in total.";
                            //TrialMessageBox.lblMessage2.Text = "Return cannot be generated as the trial version supports only 1 return in total";
                            ////TrialMessageBox.lblMessage2.Text = "Return cannot be generated as the trial version supports only 1 Regular & 1 Correction return.";
                            //-- 2025/08/29
                            TrialMessageBox.lblMessage2.Text = "It supports only one Returns each for Regular & Correction.";
                            TrialMessageBox.Show();
                            return;
                        }
                        //--####################
                    }
                    else if (TDSMAN.Classes.TDSMAN.T_pVersionType == T_VERSION_TYPE.PUBLICATION_HOUSE_VERSION)
                    {
                        if (cmbQuarter.Text != T_Qtr.Q1)
                        {
                            cmnService.J_UserMessage("Only 1st Quarter can be generated in this version");
                            return;
                        }
                    }
                    //--RETURNS CAN NOT BE GENERATED IF ORPHAN DEDUCTEE FOUND
                    if (cmnService.J_ReturnInt64Value(dmlService.J_ReturnNoOfRows("SELECT COUNT(*) FROM TRN_DEDUCTEE_DETAILS WHERE CHALLAN_ID = 0 AND BASIC_INFO_ID = " + lngBasicInfoID, J_QueryType.DirectQuery)) > 0)
                    {
                        cmnService.J_UserMessage("Returns cannot be generated as there are untagged deductee records.", MessageBoxIcon.Exclamation);
                        return;
                    }
                    //-- 2019/05/11
                    //--RETURNS CAN NOT BE GENERATED IF SALARY DETAIL ENTERED IN OLD FORMAT [FVU 6.2]
                    if (Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)) >= T_FinancialYearID.F2018_19ID &&
                        strFormNo == T_FormNo.F24Q &&
                        cmbQuarter.Text == T_Qtr.Q4)
                    {
                        strSQL = "SELECT COUNT(*) FROM TRN_SALARY_DETAILS WHERE FORM16B_NEW_FORMAT_18_19 = 0 AND BASIC_INFO_ID = " + lngBasicInfoID;
                        if (cmnService.J_ReturnInt16Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))) > 0)
                        {
                            cmnService.J_UserMessage("Returns cannot be generated as Salary Details has been entered in OLD FORMAT.", MessageBoxIcon.Exclamation);
                            return;
                        }
                    }
                    //--########################### 2019/01/02
                    if (TdsMan.LimitEditions(lngBasicInfoID, false, false, true, "TRN_DEDUCTEE_DETAILS", "BASIC_INFO_ID", "", "") == false)
                    //if (TdsMan.LimitEditions(lngBasicInfoID, false, false, true, "", "") == false)
                    {
                        dmlService.J_Rollback();
                        return;
                    }
                    //--########################### 
                    //-- NIL CHALLAN ACCEPETD FOR 24Q-Q4
                    if (strFormNo != T_FormNo.F24Q || cmbQuarter.Text != T_Qtr.Q4)
                    {
                        //-- ANIK @ 2013/09/26 for FVU 4.0
                        strSQL = "SELECT COUNT(*) " +
                                 "FROM  TRN_CHALLAN " +
                                 "LEFT JOIN (SELECT COUNT(*) AS COUNT_REC, CHALLAN_ID FROM TRN_DEDUCTEE_DETAILS GROUP BY CHALLAN_ID) AS DED " +
                                 "ON TRN_CHALLAN.CHALLAN_ID       = DED.CHALLAN_ID " +
                                 "WHERE TRN_CHALLAN.BASIC_INFO_ID = " + lngBasicInfoID + " " +
                                 "AND   " + cmnService.J_SQLDBFormat("DED.COUNT_REC", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + " = 0 " +
                                 "AND   TRN_CHALLAN.TOT_TAX       = 0";
                        if (Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strSQL)) > 0)
                        {
                            cmnService.J_UserMessage("Nil challans/transfer vouchers need to mandatorily have Deductee records");
                            return;
                        }
                    }
                    //-- Quarter Q4, SD records are mandatory, so count of salary statement records must be greater than 0 (zero) 
                    if (strFormNo == T_FormNo.F24Q && cmbQuarter.Text == T_Qtr.Q4)
                    {
                        strSQL = "SELECT COUNT(*) " +
                                 "FROM  TRN_SALARY_DETAILS " +
                                 "WHERE BASIC_INFO_ID = " + lngBasicInfoID + " ";
                        if (Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strSQL)) == 0)
                        {
                            cmnService.J_UserMessage("Salary Detail records are mandatory for Form 24Q and Q4...");
                            btnSalaryDetail.Select();
                            return;
                        }
                    }
                    else //-- 2025/07/02
                    {
                        strSQL = "SELECT COUNT(*) " +
                                "FROM  TRN_DEDUCTEE_DETAILS " +
                                "WHERE BASIC_INFO_ID = " + lngBasicInfoID + " ";
                        if (Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strSQL)) == 0)
                        {
                            cmnService.J_UserMessage("At least one deductee/colletee record is required in TDS/TCS statement as per Income Tax Department guidelines.\nPlease add deductee/colletee details before validating the statement.");
                            BtnCancel.Select();
                            return;
                        }
                    }
                    //-- 2024/04/01
                    //btnValidateTextFile.Text ="Create FVU - " + Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT MAX(FVU_VERSION) FROM MST_ASSESSMENT")) + " file";
                    //-- 2026/07/01
                    btnValidateTextFile.Text = "Create FVU - " + Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT FVU_VERSION FROM MST_ASSESSMENT WHERE ASST_ID = " + Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)))) + " file";
                    //btnValidateTextFile.Height = 25;
                    //btnPrint27A.Height = 25;
                    //--
                    //@@@@@@@@@@@@@@@@@@@@@@@@@@@@
                    ////-- 2016/09/17 MESSAGE FOR FVU 5.2
                    //if (Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)) >= T_FinancialYearID.F2016_17ID)
                    //{
                    //    if (strFormNo == T_FormNo.F27Q || (strFormNo == T_FormNo.F24Q && cmbQuarter.Text == T_Qtr.Q4))
                    //    {
                    //        cmnService.J_UserMessage("As per FVU 5.2 (released on 17th Sep 2016 and applicable from 17th Sep 2016) several changes have been directed " +
                    //            "in Form 24Q (Q4) and 27Q (all quarters).\nThese are under process of implementation in the software and would be updated by 26th Sep 2016 or earlier.");
                    //        return;
                    //    }
                    //}
                    ////
                    //if (Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)) >= T_FinancialYearID.F2013_14ID)
                    //{
                    //    if (strFormNo == T_FormNo.F24Q && cmbQuarter.Text == T_Qtr.Q4)
                    //    {
                    //        cmnService.J_UserMessage("As per FVU 5.2 (released on 17th Sep 2016 and applicable from 17th Sep 2016) several changes have been directed " +
                    //            "in Form 24Q (Q4) and 27Q (all quarters).\nThese are under process of implementation in the software and would be updated by 26th Sep 2016 or earlier.");
                    //        return;
                    //    }
                    //}
                    ////--
                    //@@@@@@@@@@@@@@@@@@@@@@@@@@@@
                    //--
                    if (cmbRegularStatement.Text == T_YES_NO.YES && txtPrevTokenNo.Text == "")
                    {
                        cmnService.J_UserMessage("Enter Token No. of previous regular statement (" + strFormNo + ")");
                        txtPrevTokenNo.Select();
                        return;
                    }
                    //-- RESPONSIBLE PERSON PAN CHECKING 2015/04/21
                    if (txtRPPAN.Text.Trim() == "")
                    {
                        //                        strSQL = @"SELECT P_PAN 
                        //                                   FROM   MST_COMPANY
                        //                                   WHERE  COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex));
                        //                        strSQL = @"SELECT P_PAN 
