                        #endregion
                        //
                        if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                            strActualAmtCreation = @"CASE WHEN " + strTableName + "." + strFieldPAN + " = 'PANNOTAVBL' " +
                                                   @"OR " + strTableName + "." + strFieldPAN + " = 'PANAPPLIED' " +
                                                   @"OR " + strTableName + "." + strFieldPAN + " = 'PANINVALID'  " +
