                        else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                        {
                            strActualAmtCreation = @"IIF(" + strTableName + "." + strFieldPAN + " = 'PANNOTAVBL' " +
                                                       @"OR " + strTableName + "." + strFieldPAN + " = 'PANAPPLIED' " +
                                                       @"OR " + strTableName + "." + strFieldPAN + " = 'PANINVALID' " +
                                                       @"OR MST_VERIFIED_PAN.VERIFIED_STATUS IN(1, 2), " +
                                                       @"ROUND(VAL(FORMAT((TRN_SALARY_DETAILS.TAXABLE_AMOUNT * 20 ) / 100, '0')),0))";
                        }
                        strSQL = @"SELECT COUNT(*) 
                               FROM   ((TRN_SALARY_DETAILS 
                               INNER JOIN " + strTableName + @"
                                   ON TRN_SALARY_DETAILS.EMPLOYEE_ID    = " + strTableName + "." + strFieldId + @") 
                               LEFT JOIN MST_VERIFIED_PAN
                                   ON  " + strTableName + "." + strFieldPAN + @" = MST_VERIFIED_PAN.PAN)
                               WHERE  TRN_SALARY_DETAILS.BASIC_INFO_ID = " + lngBasicInfoID + " " +
                             @"AND    TRN_SALARY_DETAILS.TOTAL_TAX_DEDUCTED_AMOUNT < " + strActualAmtCreation + " ";
                        long lngShortDeductionsCount = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));
                        if (lngShortDeductionsCount > 0)
