                    txtChallanSrlNo.Text = Convert.ToString(dmlService.J_ReturnMaxValue("TRN_CHALLAN", "SL_NO", "BASIC_INFO_ID = " + lngBasicInfoID + "") + 1);
                }
                else if (lblSearchMode.Text == Tabbed_Mode.Deductee)
                {
                    BackgroundColorChangeDeductee(lblMode.Text);

                    grpSearchDeductee.Visible = false;

                    strCheckFields = "";
                    strSQL = strQuery + "order by " + strOrderBy;
                    //-----------------------------------------------------------
                    if (dsetGridClone != null) dsetGridClone.Clear();
                    dsetGridClone = dmlService.J_ShowDataInGrid(ref dgcViewDeductee, strSQL, strMatrix);       //Show Data into the Grid
                    if (dsetGridClone == null) return;
                    //-----------------------------------------------------------
                    //dmlService.J_setGridPosition(ref dgcViewDeductee, dsetGridClone, "DEDUCTEE_DETAIL_ID", lngDeducteeDetailID);
                    dmlService.J_setGridPosition(ref dgcViewDeductee, dsetGridClone, lngDeducteeDetailID);
                    //
                    //txtDeducteeSrlNo.Text = Convert.ToString(dmlService.J_ReturnMaxValue("TRN_DEDUCTEE_DETAILS", "SL_NO", "CHALLAN_ID = " + lngChallanID + "") + 1);
                    //
                    if (OrphanEntry == T_DEDUCTEE_FIRST_MODULES.NORMAL)
                        txtDeducteeSrlNo.Text = Convert.ToString(dmlService.J_ReturnMaxValue("TRN_DEDUCTEE_DETAILS", "SL_NO", "CHALLAN_ID = " + lngChallanID + "") + 1);
                    else if (OrphanEntry == T_DEDUCTEE_FIRST_MODULES.DEDUCTEE)
                        txtDeducteeSrlNo.Text = Convert.ToString(dmlService.J_ReturnMaxValue("TRN_DEDUCTEE_DETAILS", "SL_NO", " CHALLAN_ID = 0 AND BASIC_INFO_ID = " + lngBasicInfoID + "") + 1);
                }
                //-----------------------------------------------------------
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion


        #region BtnDelete_Click

        private void BtnDelete_Click(object sender, EventArgs e)
        {
            try
            {
                if (BtnDelete.Text == "&Delete")
                {
                    if (lblMode.Text == J_Mode.Edit)
                        return;

                    lblMode.Text = J_Mode.Delete;

                    grpSearch.Visible = false;
                    grpSearchDeductee.Visible = false;

                    Insert_Update_Delete_Data();

                    if (lblSearchMode.Text == Tabbed_Mode.Challan)
                        dgcViewChallan_Click(sender, e);
                    else
                        dgcViewDeductee_Click(sender, e);
                }
                else
                {
                    //-- Added By Abhishek Dey On 01/10/2019 --
                    #region IS COMPANY ACCESSABLE FOR CLIENT
                    if (TDSMAN.Classes.TDSMAN.T_ClientServerMachine == T_CLIENT_SERVER_MACHINE.CLIENT_MACHINE)
                    {
                        if (dmlService.J_IsDatabaseObjectExist("TRN_TAN_USER") == true)
                        {
                            if (TdsMan.IsCompanyAccessible(Convert.ToInt64(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)), TDSMAN.Classes.TDSMAN.T_MACHINE_ID) == false)
                            {
                                cmnService.J_UserMessage("You are not authorised to proceed");
                                BtnCancel.Select();
                                return;
                            }

                            //if (Convert.ToInt32(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(*) FROM TRN_TAN_USER WHERE SETUP_ID = " + TDSMAN.Classes.TDSMAN.T_MACHINE_ID + " AND COMPANY_ID = " + )) > 0)

                        }
                    }
                    #endregion
                    //-----------------------------------------

                    //--
                    strSQL = "SELECT COUNT(*) FROM TRN_CHALLAN WHERE BASIC_INFO_ID = " + lngBasicInfoID;
                    if (Convert.ToInt64(dmlService.J_ExecSqlReturnScalar(strSQL)) == 0)
                    {
                        cmnService.J_UserMessage("No challan found", MessageBoxIcon.Information);
                        return;
                    }
                    //--
                    TDSMAN.Classes.TDSMAN.T_pFinancialYear = cmbFinancialYear.Text;
                    TDSMAN.Classes.TDSMAN.T_pQuarter = cmbQuarter.Text;
                    TDSMAN.Classes.TDSMAN.T_pCompanyName = cmbCompany.Text;
                    TDSMAN.Classes.TDSMAN.T_pCompanyId = Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex));
                    TDSMAN.Classes.TDSMAN.T_pFinancialYearId = Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex));
                    TDSMAN.Classes.TDSMAN.T_pFormNo = strFormNo;
                    TDSMAN.Classes.TDSMAN.T_pBasicInfoId = lngBasicInfoID;
                    //
                    TrnTagDeductees TagDeductees = new TrnTagDeductees();
                    TagDeductees.MdiParent = TrnRegularReturn.ActiveForm;
                    TagDeductees.Show();
                }
            }
            catch (Exception err)
            {
                cmnService.J_UserMessage(err.Message);
            }
        }

        #endregion

