        #region cmbMain_SelectedIndexChanged
        private void cmbMain_SelectedIndexChanged(object sender, EventArgs e)
        {
            if (cmbFinancialYear.SelectedIndex <= 0)
            {
                ClearControls();
                tbcCompany.Visible = false;
                ControlSummaryVisible(false, false, false, false, false, false, false);
                ReturnFilingStatusVisible(false, false, false, false, false, false);
                //
                // GENERATE RETURNS
                BtnCancel.Visible = false;
                btnChallanDeducteeEntry.Visible = false;
                btnSalaryDetail.Visible = false; btn194PAnnexureIII.Visible = false;
                if (OrphanEntry > 0)
                    BtnDelete.Visible = false;
                return;
            }
            if (cmbCompany.SelectedIndex <= 0)
            {
                ClearControls();
                tbcCompany.Visible = false;
                ControlSummaryVisible(false, false, false, false, false, false, false);
                ReturnFilingStatusVisible(false, false, false, false, false, false);
                //
                // GENERATE RETURNS
                BtnCancel.Visible = false;
                btnChallanDeducteeEntry.Visible = false;
                btnSalaryDetail.Visible = false; btn194PAnnexureIII.Visible = false;
                if (OrphanEntry > 0)
                    BtnDelete.Visible = false;
                return;
            }
            if (cmbQuarter.Text == "")
            {
                ClearControls();
                tbcCompany.Visible = false;
                ControlSummaryVisible(false, false, false, false, false, false, false);
                ReturnFilingStatusVisible(false, false, false, false, false, false);
                //
                // GENERATE RETURNS
                BtnCancel.Visible = false;
                btnChallanDeducteeEntry.Visible = false;
                btnSalaryDetail.Visible = false; btn194PAnnexureIII.Visible = false;
                if (OrphanEntry > 0)
                    BtnDelete.Visible = false;
                return;
            }
            //-----------------------------------------------
            ClearControls();
            //-----------------------------------------------
            lngBasicInfoID = TdsMan.T_ReturnBasicInfoId(dmlService.J_pCommand, Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)),
                                                        cmbQuarter.Text,
                                                        Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)),
                                                        strFormNo);
            //--
            ////Added by Indrajit on 22-02-2013 to incorporate Basic Info locking
            //#region INCORPORATE_BASIC_NFO_LOCKING

            //TDSMAN.Classes.TDSMAN.T_pBasicInfoId = lngBasicInfoID;
            ////================================================
            //if (TdsMan.LockBasicInfoEntry(T_MODULENAME.FORM_26Q) == false)
            //{
            //    //cmbStartingChequeNo.SelectedIndex = 0;
            //    //lblChequeLeavesAvailable.Visible = false;
            //    BtnExit.Select();
            //    return;
            //}
            //#endregion
            if (LoadBasicDetails(Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)), lngBasicInfoID) == true)
            {
                tbcCompany.Enabled = true;
                tbcCompany.Visible = true;
                //
                // GENERATE RETURNS
                BtnCancel.Visible = true;
                BtnCancel.Text = "Generate Returns";
                btnChallanDeducteeEntry.Visible = true;
                //--
                if (strFormNo == T_FormNo.F24Q && cmbQuarter.Text == T_Qtr.Q4)
                {
                    //--COMMENTED TEMPORARILY ON 2019/05/14
                    btnSalaryDetail.Visible = true;
                    //btnSalaryDetail.Width = 215;
                    //////btnSalaryDetail.Location = new Point(394, 48);
                    //
                    lblNetTaxableIncome.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(TOTAL_INCOME) AS NET_TAXABLE_INCOME FROM TRN_SALARY_DETAILS WHERE BASIC_INFO_ID = " + lngBasicInfoID)) == "" ? "0.00" : Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(TOTAL_INCOME) AS NET_TAXABLE_INCOME FROM TRN_SALARY_DETAILS WHERE BASIC_INFO_ID = " + lngBasicInfoID))));
                    //
                    if (cmnService.J_ReturnDoubleValue(lblNetTaxableIncome.Text) > 0)
                    {
                        //--
                        lblNetTaxableIncomeCaption.Visible = true;
                        lblNetTaxableIncome.Visible = true;
                        //--
                        //if (TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.PROFESSIONAL_EDITION)
                        //    btnBulkPANVerification.Visible = true;
                    }
                    else
                    {
                        //--
                        lblNetTaxableIncomeCaption.Visible = false;
                        lblNetTaxableIncome.Visible = false;
                        //--
                        btnBulkPANVerification.Visible = false;
                    }
                    //-- 194P
                    if (Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)) >= T_FinancialYearID.F2021_22ID &&
                            Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SECTION_194P_FLAG FROM MST_COMPANY WHERE COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)))) == "1")
                    {
                        btn194PAnnexureIII.Visible = true;
                        //
                        //btnSalaryDetail.Width = 215;// 175;
                        //////btnSalaryDetail.Location = new Point(327, 48);
                        //
                        //btn194PAnnexureIII.Width = 215;// 175;
                        //////btn194PAnnexureIII.Location = new Point(504, 48);
                    }
                    else
                        btn194PAnnexureIII.Visible = false;
                    //--
                }
                else
                {
                    btnSalaryDetail.Visible = false; btn194PAnnexureIII.Visible = false;
                    //--
                    lblNetTaxableIncomeCaption.Visible = false;
                    lblNetTaxableIncome.Visible = false;
                }
            }
            else
            {
                return;
            }
            //-----------------------------------------------
            EnabilityNILReturn(lngBasicInfoID);
            EnabilityAddressChange(lngBasicInfoID);
            EnabilityReturnFilingStatus(lngBasicInfoID);
            //-- ANIK @ 2014-01-29
            string strPrevTokenNo = TdsMan.GetPreviousTokenNo(Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)), cmbQuarter.Text, strFormNo, Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)));
            //
            if (strPrevTokenNo != "" && txtPrevTokenNo.Text == "" && cmbRegularStatement.Text == T_YES_NO.YES)
                txtPrevTokenNo.Text = strPrevTokenNo;
            // CONTROL SUMMARY
            ControlSummaryBasicInfo(lngBasicInfoID);
            //
            EnabilityGrpButtons(lngBasicInfoID);
            //           
            if (OrphanEntry == T_DEDUCTEE_FIRST_MODULES.DEDUCTEE) //-- 2014/12/12
            {
                btnChallanDeducteeEntry.Text = Tabbed_Mode.DeducteeFirst;
                //
                //BtnCancel.Enabled = false;
                //BtnCancel.BackColor = Color.LightGray;
                BtnDelete.Visible = true;
                BtnDelete.Enabled = true;
                BtnDelete.BackColor = Color.Lavender;
                //
                BtnCancel.Visible = false;
                btnSalaryDetail.Visible = false; btn194PAnnexureIII.Visible = false;
                //
                grpLastProvisionalReceiptNo.Enabled = false;
                grpAddressChange.Enabled = false;
                //--
                ControlSummaryBasicInfoOrphan(lngBasicInfoID);
            }
            else if (OrphanEntry == T_DEDUCTEE_FIRST_MODULES.CHALLAN) //-- 2014/12/12
            {
                btnChallanDeducteeEntry.Text = Tabbed_Mode.Challan;
                //
                BtnCancel.Enabled = false;
                BtnCancel.BackColor = Color.LightGray;
                //
                grpLastProvisionalReceiptNo.Enabled = false;
                grpAddressChange.Enabled = false;
            }
            //--
            lblSelectReturn.ForeColor = Color.DodgerBlue;
        }
