        #region txtBSRCode_TextChanged
        private void txtBSRCode_TextChanged(object sender, EventArgs e)
        {
            IDataReader drdShowBSRCodeHelp = null;
            //
            try
            {
                //--
                if (txtBSRCode.Text.Trim() == "")
                {
                    lstBSRCodeList.Visible = false;
                    return;
                }
                //--
                if (blnShowBSRCodeHelp == false) return;
                //--
                string strSQLBSRCodeHelp = "";
                //--
                if (txtBSRCode.Text.Length == 1)
                {
                    strSQLBSRCodeHelp = @"SELECT DISTINCT TRN_CHALLAN.BSR_CODE  
                                          FROM   TRN_CHALLAN, 
                                                 TRN_BASIC_INFO, 
                                                 MST_COMPANY
                                          WHERE  TRN_CHALLAN.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID
                                          AND    TRN_BASIC_INFO.COMPANY_ID = MST_COMPANY.COMPANY_ID
                                          AND    TRN_CHALLAN.BSR_CODE      <> ''
                                          AND    MST_COMPANY.TAN_NO        = '" + txtTAN.Text + "' ";
                    if (chkBookEntry.Checked == false)
                        strSQLBSRCodeHelp = strSQLBSRCodeHelp + " AND TRN_CHALLAN.BOOK_ENTRY = 0 ";
                    else if (chkBookEntry.Checked == true)
                        strSQLBSRCodeHelp = strSQLBSRCodeHelp + " AND TRN_CHALLAN.BOOK_ENTRY = 1 ";
                    //
                    strSQLBSRCodeHelp = strSQLBSRCodeHelp + " ORDER BY TRN_CHALLAN.BSR_CODE ";
                    //
                    drdShowBSRCodeHelp = dmlService.J_ExecSqlReturnReader(strSQLBSRCodeHelp);
                    //--
                    if (drdShowBSRCodeHelp == null)
                    {
                        lstBSRCodeList.Visible = false;
                        return;
                    }
                    else
                    {
                        //--
                        lstBSRCodeList.Items.Clear();
                        //lstBSRCodeList.Height = 19;
                        lstBSRCodeList.Visible = true;
                        //--
                        while (drdShowBSRCodeHelp.Read())
                        {
                            lstBSRCodeList.Items.Add(new ListBoxItem(drdShowBSRCodeHelp["BSR_CODE"].ToString()));
                            //--
                            //if (lstBSRCodeList.Height <= 300)
                            //    lstBSRCodeList.Height = lstBSRCodeList.Height + 19;
                        }
                        //--
                        if (lstBSRCodeList.Items.Count <= 0)
                            lstBSRCodeList.Visible = false;
                        //--
                    }
                    //-----------------------------------------------------------
                    drdShowBSRCodeHelp.Close();
                    drdShowBSRCodeHelp.Dispose();
                }
                else if (txtBSRCode.Text.Length > 1)
                {
                    strSQLBSRCodeHelp = @"SELECT DISTINCT BSR_CODE 
                                          FROM   TRN_CHALLAN, 
                                                 TRN_BASIC_INFO, 
                                                 MST_COMPANY
                                          WHERE  TRN_CHALLAN.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID
                                          AND    TRN_BASIC_INFO.COMPANY_ID = MST_COMPANY.COMPANY_ID
                                          AND    TRN_CHALLAN.BSR_CODE      <> ''
                                          AND    TRN_CHALLAN.BSR_CODE LIKE '" + txtBSRCode.Text + @"%'
                                          AND    MST_COMPANY.TAN_NO        = '" + txtTAN.Text + "'";
                    if (chkBookEntry.Checked == false)
                        strSQLBSRCodeHelp = strSQLBSRCodeHelp + " AND TRN_CHALLAN.BOOK_ENTRY = 0 ";
                    else if (chkBookEntry.Checked == true)
                        strSQLBSRCodeHelp = strSQLBSRCodeHelp + " AND TRN_CHALLAN.BOOK_ENTRY = 1 ";
                    //
                    strSQLBSRCodeHelp = strSQLBSRCodeHelp + " ORDER BY TRN_CHALLAN.BSR_CODE ";
                    //
                    drdShowBSRCodeHelp = dmlService.J_ExecSqlReturnReader(strSQLBSRCodeHelp);
                    //--
                    if (drdShowBSRCodeHelp == null)
                    {
                        lstBSRCodeList.Visible = false;
                        return;
                    }
                    else
                    {
                        lstBSRCodeList.Items.Clear();
                        //lstBSRCodeList.Height = 19;
                        lstBSRCodeList.Visible = true;
                        while (drdShowBSRCodeHelp.Read())
                        {
                            lstBSRCodeList.Items.Add(new ListBoxItem(drdShowBSRCodeHelp["BSR_CODE"].ToString()));
                            //--
                            //if (lstBSRCodeList.Height <= 300)
                            //    lstBSRCodeList.Height = lstBSRCodeList.Height + 19;
                        }
                        //--
                        if (lstBSRCodeList.Items.Count <= 0)
                            lstBSRCodeList.Visible = false;
                        //--
                    }
                    //-----------------------------------------------------------
                    drdShowBSRCodeHelp.Close();
                    drdShowBSRCodeHelp.Dispose();
                }
                else if (txtBSRCode.Text.Length <= 0)
                {
                    lstBSRCodeList.Visible = false;
                    return;
                }
            }
            catch (Exception err_handler)
            {
                drdShowBSRCodeHelp.Close();
                drdShowBSRCodeHelp.Dispose();
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

        #region txtBSRCode_KeyDown
        private void txtBSRCode_KeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Down || e.KeyCode == Keys.Right)
            {
                if (lstBSRCodeList.Visible == true)
                {
                    lstBSRCodeList.Focus();
                    lstBSRCodeList.SelectedIndex = 0;
                }
            }
            else if (e.KeyCode == Keys.Tab)
            {
                lstBSRCodeList.Visible = false;
            }
        }
        #endregion

        #region lstBSRCodeList_KeyPress
        private void lstBSRCodeList_KeyPress(object sender, KeyPressEventArgs e)
        {
            if (Convert.ToInt64(e.KeyChar) == 13)
                lstBSRCodeList_Click(sender, e);
            else if (Convert.ToInt64(e.KeyChar) == 27)
            {
                lstBSRCodeList.Visible = false;
                txtBSRCode.Select();
            }
        }
        #endregion


