        {
            IDataReader drdShowDeducteeHelp = null;
            //--
            try
            {
                if (txtDeducteeName.Text.Trim() == "")
                {
                    lstDeducteeNameHelp.Visible = false;
                    TdsMan.GetSetup();
                    return;
                }
                //--
                if (blnShowHelp == false)
                    return;
                //-----------------------
                if (strFormNo == T_FormNo.F24Q)
                {
                    //-----------------------
                    string[,] strShowHelpEmployeeMatrix = {{"MST_EMPLOYEE.CATEGORY = 'G'", "F", "GENERAL", "T"},
                                                       {"MST_EMPLOYEE.CATEGORY = 'W'", "F", "WOMAN", "T"},
                                                       {"MST_EMPLOYEE.CATEGORY = 'S'", "F", "SENIOR CITIZEN", "T"},
                                                       {"MST_EMPLOYEE.CATEGORY = 'O'", "F", "VERY SENIOR CITIZEN", "T"},
                                                       {"MST_EMPLOYEE.CATEGORY = ''", "F", "", "T"}};
                    //
                    strSQLShowHelpDeductee = "SELECT EMPLOYEE_ID," +
                        "                            LEFT(EMPLOYEE_NAME, 50) AS EMPLOYEE_NAME," +
                        "                            EMPLOYEE_PAN," +
                        "                            " + cmnService.J_SQLDBFormat(strShowHelpEmployeeMatrix, J_SQLColFormat.Case_End) + " AS CATEGORY " +
                        "                     FROM   MST_EMPLOYEE," +
                        "                            MST_COMPANY " +
                        "                     WHERE  MST_EMPLOYEE.COMPANY_ID = MST_COMPANY.COMPANY_ID " +
                        "                     AND    MST_COMPANY.COMPANY_ID  = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + " " +
                        "                     AND    EMPLOYEE_NAME       LIKE '" + TDSMAN.Classes.TDSMAN.T_DeducteeSearchLikeOperator + cmnService.J_ReplaceQuote(txtDeducteeName.Text) + "%' " +
                        "                     AND    MST_EMPLOYEE.INACTIVE_FLAG = 0 " +
                        "                     ORDER BY LEFT(EMPLOYEE_NAME, 50), EMPLOYEE_ID";
                }
                else
                {
                    if (TDSMAN.Classes.TDSMAN.T_ShowCompanyWiseDeductee == true)
                    {
                        lstDeducteeNameHelp.BackColor = Color.LightSkyBlue;
                        //--
                        strSQLShowHelpDeductee = "SELECT DISTINCT DEDUCTEE_ID," +
                                                 "       LEFT(DEDUCTEE_NAME, 50) AS DEDUCTEE_NAME," +
                                                 "       DEDUCTEE_PAN," +
                                                 "       MST_DEDUCTEE.DEDUCTEE_CODE " +
                                                 "FROM   MST_DEDUCTEE, " +
                                                 "       TRN_BASIC_INFO, " +
                                                 "       TRN_DEDUCTEE_DETAILS " +
                                                 "WHERE  MST_DEDUCTEE.DEDUCTEE_ID = TRN_DEDUCTEE_DETAILS.PARTY_ID " +
                                                 "AND    TRN_BASIC_INFO.BASIC_INFO_ID = TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID " +
                                                 "AND    TRN_BASIC_INFO.COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + " " +
                                                 "AND    TRN_BASIC_INFO.FORM_NO    <> '24Q' " +
                                                 "AND    MST_DEDUCTEE.INACTIVE_FLAG = 0 " +
                                                 "AND    DEDUCTEE_NAME LIKE '" + TDSMAN.Classes.TDSMAN.T_DeducteeSearchLikeOperator + cmnService.J_ReplaceQuote(txtDeducteeName.Text) + "%' " +
                                                 "ORDER BY LEFT(DEDUCTEE_NAME, 50), DEDUCTEE_ID";
                    }
                    else
                    {
                        lstDeducteeNameHelp.BackColor = Color.MistyRose;
                        //--
                        strSQLShowHelpDeductee = "SELECT DEDUCTEE_ID," +
                                                 "       LEFT(DEDUCTEE_NAME, 50) AS DEDUCTEE_NAME," +
                                                 "       DEDUCTEE_PAN," +
                                                 "       MST_DEDUCTEE.DEDUCTEE_CODE " +
                                                 "FROM   MST_DEDUCTEE " +
                                                 "WHERE  DEDUCTEE_NAME LIKE '" + TDSMAN.Classes.TDSMAN.T_DeducteeSearchLikeOperator + cmnService.J_ReplaceQuote(txtDeducteeName.Text) + "%' " +
                                                 "AND    MST_DEDUCTEE.INACTIVE_FLAG = 0 " +
                                                 "ORDER BY LEFT(DEDUCTEE_NAME, 50), DEDUCTEE_ID";
                    }
                }

                drdShowDeducteeHelp = dmlService.J_ExecSqlReturnReader(strSQLShowHelpDeductee);
                //--
                if (drdShowDeducteeHelp == null)
                {
                    lstDeducteeNameHelp.Visible = false;
                    return;
                }
                else
                {
                    lstDeducteeNameHelp.Items.Clear();
                    //lstDeducteeNameHelp.Height = 19;
                    lstDeducteeNameHelp.Visible = true;
                    lstDeducteeNameHelp.Location = new Point(4, 88);
                    while (drdShowDeducteeHelp.Read())
                    {
                        if (strFormNo == T_FormNo.F24Q)
                            lstDeducteeNameHelp.Items.Add(new ListBoxItem(drdShowDeducteeHelp[strEmpDed + "_NAME"].ToString().PadRight(58) + drdShowDeducteeHelp[strEmpDed + "_PAN"].ToString().PadRight(13)));
                        else
                            lstDeducteeNameHelp.Items.Add(new ListBoxItem(drdShowDeducteeHelp[strEmpDed + "_NAME"].ToString().PadRight(58) + drdShowDeducteeHelp[strEmpDed + "_PAN"].ToString().PadRight(13) + drdShowDeducteeHelp["DEDUCTEE_CODE"]));
                        //--
                        //if (lstDeducteeNameHelp.Height <= 300)
                        //    lstDeducteeNameHelp.Height = lstDeducteeNameHelp.Height + 19;
                    }
                    //--
                    if (lstDeducteeNameHelp.Items.Count <= 0)
                        lstDeducteeNameHelp.Visible = false;
                    //--
                    if (TDSMAN.Classes.TDSMAN.T_ShowCompanyWiseDeductee == true && strFormNo != T_FormNo.F24Q)
                    {
                        lstDeducteeNameHelp.Items.Add(new ListBoxItem(strHelpLastLineText));
                        //if (lstDeducteeNameHelp.Height <= 300) 
                        //    lstDeducteeNameHelp.Height = lstDeducteeNameHelp.Height + 25;
                    }
                    //--
                }
                //-----------------------------------------------------------
                drdShowDeducteeHelp.Close();
                drdShowDeducteeHelp.Dispose();
                //-----------------------------------------------------------
            }
            catch (Exception err_handler)
            {
                drdShowDeducteeHelp.Close();
                drdShowDeducteeHelp.Dispose();
                cmnService.J_UserMessage(err_handler.Message);
            }
            //-----------------------
        }
        #endregion

        #region txtDeducteeName_KeyPress
        private void txtDeducteeName_KeyPress(object sender, KeyPressEventArgs e)
        {
            if (Convert.ToInt64(e.KeyChar) == 13)
            {
                if (lstDeducteeNameHelp.Visible == true)
                {
                    lstDeducteeNameHelp.Focus();
                    lstDeducteeNameHelp.SelectedIndex = 0;
                }
                else
                    SendKeys.Send("{tab}");
            }
        }
        #endregion

        #region txtDeducteeName_KeyDown
        private void txtDeducteeName_KeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Down || e.KeyCode == Keys.Right)
            {
                if (lstDeducteeNameHelp.Visible == true)
                {
                    lstDeducteeNameHelp.Focus();
                    lstDeducteeNameHelp.SelectedIndex = 0;
                }
            }
            //
            if (e.KeyCode == Keys.F1)
            {
                TDSMAN.Classes.TDSMAN.T_ShowCompanyWiseDeductee = false;
                txtDeducteeName_TextChanged(sender, e);
            }
        }
        #endregion

        #region txtDeducteeName_Leave
        private void txtDeducteeName_Leave(object sender, EventArgs e)
        {
            //if (lstDeducteeHelp.Visible == true) lstDeducteeHelp.Visible = false;
