        #region txtDeducteePAN_Leave
        private void txtDeducteePAN_Leave(object sender, EventArgs e)
        {
            if (txtDeducteePAN.Text.Trim() == "") txtDeducteePAN.Text = "PANNOTAVBL";
            //lstPANHelp.Visible = false;
            //-- Added By Abhishek Dey On 13/04/2018 --
            else if (strFormNo != T_FormNo.F24Q)
            {
                if (strFormNo == T_FormNo.F26Q)
                {
                    if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "C")
                        cmbDeducteeCode.SelectedIndex = 0;
                    else
                        cmbDeducteeCode.SelectedIndex = 1;
                }
                else
                {
                    if (txtDeducteePAN.Text.Length > 2)
                    {
                        #region COMMENT
                        //if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "C")
                        //    cmbDeducteeCode.Text = T_DeducteeCodeDesc.Company;
                        ////else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "P")
                        ////    cmbDeducteeCode.Text = T_DeducteeCodeDesc.;
                        //else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "H")
                        //    cmbDeducteeCode.Text = T_DeducteeCodeDesc.HinduUndividedFamily;
                        //else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "A")
                        //    cmbDeducteeCode.Text = T_DeducteeCodeDesc.AOPConsistingAsitsMembers;
                        //else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "B")
                        //    cmbDeducteeCode.Text = T_DeducteeCodeDesc.BodyOfIndividuals;
                        ////else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "G")
                        ////    cmbDeducteeCode.Text = T_DeducteeCodeDesc.;
                        //else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "J")
                        //    cmbDeducteeCode.Text = T_DeducteeCodeDesc.ArtificialJuridicalPerson;
                        ////else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "L")
                        ////    cmbDeducteeCode.Text = T_DeducteeCodeDesc.;
                        //else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "F")
                        //    cmbDeducteeCode.Text = T_DeducteeCodeDesc.Firm;
                        ////else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "T")
                        ////    cmbDeducteeCode.Text = T_DeducteeCodeDesc.;
                        //else
                        //    cmbDeducteeCode.Text = T_DeducteeCodeDesc.Others;
                        #endregion
                        //
                        if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "C")
                            cmbDeducteeCode.Text = T_DeducteeCodeDesc.Company;
                        else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "P")
                            cmbDeducteeCode.Text = T_DeducteeCodeDesc.NonCompany;
                        else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "H")
                            cmbDeducteeCode.Text = T_DeducteeCodeDesc.HinduUndividedFamily;
                        else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "A")
                            cmbDeducteeCode.Text = T_DeducteeCodeDesc.AOPConsistingAsitsMembers;
                        else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "B")
                            cmbDeducteeCode.Text = T_DeducteeCodeDesc.BodyOfIndividuals;
                        else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "J")
                            cmbDeducteeCode.Text = T_DeducteeCodeDesc.ArtificialJuridicalPerson;
                        else if (txtDeducteePAN.Text.Trim().Substring(3, 1) == "F")
                            cmbDeducteeCode.Text = T_DeducteeCodeDesc.Firm;
                        else
                            cmbDeducteeCode.Text = T_DeducteeCodeDesc.Others;
                    }
                }
            }
            //-- 2018/12/07
            if (TDSMAN.Classes.TDSMAN.T_ENABLE_LOAD_SECTION_AUTO == true)
            {
                //-- LOAD/SELECT SECTION PAN WISE
                if (lblMode.Text == J_Mode.Add)
                {
                    if (txtDeducteePAN.Text != "PANNOTAVBL")
                    {
                        strSQL = @"SELECT COUNT(*)
                              FROM   TRN_DEDUCTEE_DETAILS,
                                     MST_SECTION,
                                    TRN_BASIC_INFO
                             WHERE  TRN_DEDUCTEE_DETAILS.SECTION_ID    = MST_SECTION.SECTION_ID
                             AND    TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID
                             AND    TRN_BASIC_INFO.FORM_NO             ='" + strFormNo + @"' 
                             AND    TRN_DEDUCTEE_DETAILS.PARTY_PAN     ='" + cmnService.J_ReplaceQuote(txtDeducteePAN.Text.Trim()) + "'";
                        if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))) > 0)
                        {
                            //--
                            lblCaptionLoadAllSection.Visible = true;
                            blnShowBSRCodeHelpCaption = true;
                            //--
                            strSQL = @"SELECT DISTINCT MST_SECTION.SECTION_ID,
                                          MST_SECTION.SECTION_NO
                                   FROM   TRN_DEDUCTEE_DETAILS,
                                          MST_SECTION,
                                          TRN_BASIC_INFO
                                   WHERE  TRN_DEDUCTEE_DETAILS.SECTION_ID    = MST_SECTION.SECTION_ID
                                   AND    TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID
                                   AND    TRN_BASIC_INFO.FORM_NO             ='" + strFormNo + @"' 
                                   AND    TRN_DEDUCTEE_DETAILS.PARTY_PAN     ='" + cmnService.J_ReplaceQuote(txtDeducteePAN.Text.Trim()) + @"' 
                                   ORDER BY MST_SECTION.SECTION_NO";
                            if (dmlService.J_PopulateComboBox(strSQL, ref cmbDDSection, 1) == false) return;
                        }
                        else
                        {
                            //--
                            lblCaptionLoadAllSection.Visible = false;
                            blnShowBSRCodeHelpCaption = false;
                            //LoadSections(strFormNo, ref cmbDDSection, "  AND SECTION_ID <> 27  ");
                            LoadSections(strFormNo, ref cmbDDSection, Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)), " AND SECTION_ID <> 27 "); //-- 2026/05/15

                            //--
                        }
                    }
                    else
                        blnShowBSRCodeHelpCaption = false;
                }
                else
                    blnShowBSRCodeHelpCaption = false;
            }
            //-- 
            //-- 2021/08/12
            //-- GET LAST PAYMENT AMOUNT & TDS FOR 24Q
            if (strFormNo == T_FormNo.F24Q && lblMode.Text == J_Mode.Add)
            {
                if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                    strSQL = @"SELECT TOP 1 PAYMENT_AMOUNT
                            FROM   TRN_DEDUCTEE_DETAILS,
	                               TRN_BASIC_INFO,
                                   MST_EMPLOYEE
                            WHERE  TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID
                            AND    TRN_DEDUCTEE_DETAILS.PARTY_ID      = MST_EMPLOYEE.EMPLOYEE_ID
                            AND    TRN_BASIC_INFO.FORM_NO ='" + T_FormNo.F24Q + @"' 
                            AND    TRN_BASIC_INFO.COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + @"
                            AND    MST_EMPLOYEE.EMPLOYEE_NAME ='" + cmnService.J_ReplaceQuote(txtDeducteeName.Text) + @"'
                            AND    MST_EMPLOYEE.EMPLOYEE_PAN = '" + cmnService.J_ReplaceQuote(txtDeducteePAN.Text) + @"'
                            ORDER BY CASE WHEN TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE IS NULL THEN TRN_DEDUCTEE_DETAILS.PAYMENT_DATE ELSE TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE END DESC,
		                            TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID DESC,
		                            TRN_BASIC_INFO.ASST_ID DESC,
		                            TRN_BASIC_INFO.QTR DESC";
                else

                    strSQL = @"SELECT TOP 1 PAYMENT_AMOUNT
                            FROM   TRN_DEDUCTEE_DETAILS,
	                               TRN_BASIC_INFO,
                                   MST_EMPLOYEE
                            WHERE  TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID
                            AND    TRN_DEDUCTEE_DETAILS.PARTY_ID      = MST_EMPLOYEE.EMPLOYEE_ID
                            AND    TRN_BASIC_INFO.FORM_NO ='" + T_FormNo.F24Q + @"' 
                            AND    TRN_BASIC_INFO.COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + @"
                            AND    MST_EMPLOYEE.EMPLOYEE_NAME ='" + cmnService.J_ReplaceQuote(txtDeducteeName.Text) + @"'
                            AND    MST_EMPLOYEE.EMPLOYEE_PAN = '" + cmnService.J_ReplaceQuote(txtDeducteePAN.Text) + @"'
                            ORDER BY IIF(TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE IS NULL, TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE) DESC,
		                            TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID DESC,
		                            TRN_BASIC_INFO.ASST_ID DESC,
		                            TRN_BASIC_INFO.QTR DESC";
                if (cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(strSQL)) > 0)
                {
                    if (TDSMAN.Classes.TDSMAN.T_AUTO_POPULATE_PAID_AMOUNT_TAX_AMOUNT == true)
                        txtDeducteeAmountOfPayment.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))));
                    //--
                    lblLastPayment.Text = "Last Paid Amount : " + string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))));
                }
                else
                    lblLastPayment.Text = "";
                //

                if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                    strSQL = @"SELECT TOP 1 TAX_DEPOSITED_AMOUNT
                            FROM   TRN_DEDUCTEE_DETAILS,
	                               TRN_BASIC_INFO,
                                   MST_EMPLOYEE
                            WHERE  TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID
                            AND    TRN_DEDUCTEE_DETAILS.PARTY_ID      = MST_EMPLOYEE.EMPLOYEE_ID
                            AND    TRN_BASIC_INFO.FORM_NO ='" + T_FormNo.F24Q + @"' 
                            AND    TRN_BASIC_INFO.COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + @"
                            AND    MST_EMPLOYEE.EMPLOYEE_NAME ='" + cmnService.J_ReplaceQuote(txtDeducteeName.Text) + @"'
                            AND    MST_EMPLOYEE.EMPLOYEE_PAN = '" + cmnService.J_ReplaceQuote(txtDeducteePAN.Text) + @"'
                            ORDER BY  CASE WHEN TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE IS NULL THEN TRN_DEDUCTEE_DETAILS.PAYMENT_DATE ELSE TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE END DESC,
		                            TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID DESC,
		                            TRN_BASIC_INFO.ASST_ID DESC,
		                            TRN_BASIC_INFO.QTR DESC";
                else
                    strSQL = @"SELECT TOP 1 TAX_DEPOSITED_AMOUNT
                            FROM   TRN_DEDUCTEE_DETAILS,
	                               TRN_BASIC_INFO,
                                   MST_EMPLOYEE
                            WHERE  TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = TRN_BASIC_INFO.BASIC_INFO_ID
                            AND    TRN_DEDUCTEE_DETAILS.PARTY_ID      = MST_EMPLOYEE.EMPLOYEE_ID
                            AND    TRN_BASIC_INFO.FORM_NO ='" + T_FormNo.F24Q + @"' 
                            AND    TRN_BASIC_INFO.COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + @"
                            AND    MST_EMPLOYEE.EMPLOYEE_NAME ='" + cmnService.J_ReplaceQuote(txtDeducteeName.Text) + @"'
                            AND    MST_EMPLOYEE.EMPLOYEE_PAN = '" + cmnService.J_ReplaceQuote(txtDeducteePAN.Text) + @"'
                            ORDER BY  IIF(TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE IS NULL, TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE) DESC,
		                            TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID DESC,
		                            TRN_BASIC_INFO.ASST_ID DESC,
		                            TRN_BASIC_INFO.QTR DESC";

                if (cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(strSQL)) > 0)
                {
                    if (TDSMAN.Classes.TDSMAN.T_AUTO_POPULATE_PAID_AMOUNT_TAX_AMOUNT == true)
                        txtDeducteeIncometax.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))));
                    //--
                    if (lblLastPayment.Text != "")
                        lblLastPayment.Text = lblLastPayment.Text + ", Last Tax Amount : " + string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))));
                    else
                        lblLastPayment.Text = "Last Tax Amount : " + string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))));
                }
                //else
                //    lblLastPayment.Text = "";
            }
            else
                lblLastPayment.Text = "";
        }
