        #region txtDeducteePAN_TextChanged
        private void txtDeducteePAN_TextChanged(object sender, EventArgs e)
        {
            IDataReader drdShowDeducteePanHelp = null;
            try
            {
                //--------------------------------------------------------------------
                //ADDED BY DHRUB ON 17/01/2014 FOR TDS RATE COMPANY & NONCOMPANY WISE 
                //--------------------------------------------------------------------
                ShowRate();
                //--------------------------------------------------------------------
                if (txtDeducteePAN.Text == "PANNOTAVBL" && Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)) >= T_FinancialYearID.F2010_11ID)
                {
                    if (Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)) >= T_FinancialYearID.F2012_13ID && cmbDDSection.Text == "194LC")
                    {
                        if (dtService.J_ConvertToIntYYYYMMDD(mskDeducteeDate.Text) >= 20130601)
                        {
                            lblMsgDisplay.Visible = false;
                            return;
                        }
                    }
                    //grpRemarks.Enabled = false;
                    //rbnHigherRate.Checked = true;
                    //if (strFormNo != T_FormNo.F27EQ)
                    cmbRemarks.SelectedIndex = 4;
                    //
                    lblMsgDisplay.Visible = true;
                    lblMsgDisplay.Text = "Higher rate of TDS applicable as PANNOTAVBL.";
                }
                else
                {
                    //grpRemarks.Enabled = true;
                    //rbnHigherRate.Checked = false;
                    //rbnNormal.Checked = true;
                    if (lblMode.Text == J_Mode.Add)
                        cmbRemarks.SelectedIndex = 1;

                    lblMsgDisplay.Visible = false;
                    lblMsgDisplay.Text = "";

                    //######## 2021/01/07
                    if (TDSMAN.Classes.TDSMAN.T_PARTY_SEARCH_PAN_WISE_OPTION == true)
                    {
                        if (lstDeducteeNameHelp.Visible == false && (txtDeducteePAN.Text.Trim().Length > 1 && txtDeducteePAN.Text.Trim().Length < 10))
                        {
                            if (strFormNo == T_FormNo.F24Q)
                            {
                                //-----------------------
                                string[,] strShowHelpEmployeeMatrix = {{"MST_EMPLOYEE.CATEGORY = 'G'", "F", "GENERAL", "T"},
                                                       {"MST_EMPLOYEE.CATEGORY = 'W'", "F", "WOMAN", "T"},
                                                       {"MST_EMPLOYEE.CATEGORY = 'S'", "F", "SENIOR CITIZEN", "T"},
                                                       {"MST_EMPLOYEE.CATEGORY = 'O'", "F", "VERY SENIOR CITIZEN", "T"},
                                                       {"MST_EMPLOYEE.CATEGORY = ''", "F", "", "T"}};
                                //
                                strSQLShowHelpDeductee = "SELECT EMPLOYEE_ID," +
                                    "                            EMPLOYEE_NAME," +
                                    "                            EMPLOYEE_PAN," +
                                    "                            " + cmnService.J_SQLDBFormat(strShowHelpEmployeeMatrix, J_SQLColFormat.Case_End) + " AS CATEGORY " +
                                    "                     FROM   MST_EMPLOYEE," +
                                    "                            MST_COMPANY " +
                                    "                     WHERE  MST_EMPLOYEE.COMPANY_ID = MST_COMPANY.COMPANY_ID " +
                                    "                     AND    MST_COMPANY.COMPANY_ID  = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + " " +
                                    "                     AND    EMPLOYEE_PAN       LIKE '" + TDSMAN.Classes.TDSMAN.T_DeducteeSearchLikeOperator + cmnService.J_ReplaceQuote(txtDeducteePAN.Text) + "%' " +
                                    "                     AND    MST_EMPLOYEE.INACTIVE_FLAG = 0 " +
                                    "                     ORDER BY EMPLOYEE_NAME, EMPLOYEE_ID";
                            }
                            else
                            {
                                if (TDSMAN.Classes.TDSMAN.T_ShowCompanyWiseDeductee == true)
                                {
                                    lstDeducteeNameHelp.BackColor = Color.LightSkyBlue;
                                    //--
                                    strSQLShowHelpDeductee = "SELECT DISTINCT DEDUCTEE_ID," +
                                                             "       DEDUCTEE_NAME," +
                                                             "       DEDUCTEE_PAN," +
                                                             "       MST_DEDUCTEE.DEDUCTEE_CODE " +
                                                             "FROM   MST_DEDUCTEE, " +
                                                             "       TRN_BASIC_INFO, " +
                                                             "       TRN_DEDUCTEE_DETAILS " +
                                                             "WHERE  MST_DEDUCTEE.DEDUCTEE_ID = TRN_DEDUCTEE_DETAILS.PARTY_ID " +
                                                             "AND    TRN_BASIC_INFO.BASIC_INFO_ID = TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID " +
                                                             "AND    TRN_BASIC_INFO.COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + " " +
                                                             "AND    TRN_BASIC_INFO.FORM_NO    <> '24Q' " +
                                                             "AND    MST_DEDUCTEE.INACTIVE_FLAG = 0 " +
                                                             "AND    DEDUCTEE_PAN LIKE '" + TDSMAN.Classes.TDSMAN.T_DeducteeSearchLikeOperator + cmnService.J_ReplaceQuote(txtDeducteePAN.Text) + "%' " +
                                                             "ORDER BY DEDUCTEE_NAME, DEDUCTEE_ID";
                                }
                                else
                                {
                                    lstDeducteeNameHelp.BackColor = Color.MistyRose;
                                    //--
                                    strSQLShowHelpDeductee = "SELECT DEDUCTEE_ID," +
                                                             "       DEDUCTEE_NAME," +
                                                             "       DEDUCTEE_PAN," +
                                                             "       MST_DEDUCTEE.DEDUCTEE_CODE " +
                                                             "FROM   MST_DEDUCTEE " +
                                                             "WHERE  DEDUCTEE_PAN LIKE '" + TDSMAN.Classes.TDSMAN.T_DeducteeSearchLikeOperator + cmnService.J_ReplaceQuote(txtDeducteePAN.Text) + "%' " +
                                                             "AND    MST_DEDUCTEE.INACTIVE_FLAG = 0 " +
                                                             "ORDER BY DEDUCTEE_NAME, DEDUCTEE_ID";
                                }
                            }

                            drdShowDeducteePanHelp = dmlService.J_ExecSqlReturnReader(strSQLShowHelpDeductee);
                            //--
                            if (drdShowDeducteePanHelp == null)
                            {
                                lstDeducteePANHelp.Visible = false;
                                return;
                            }
                            else
                            {
                                lstDeducteePANHelp.Items.Clear();
                                //lstDeducteePANHelp.Height = 19;
                                lstDeducteePANHelp.Visible = true;
                                lstDeducteePANHelp.Location = new Point(4, 109);
                                while (drdShowDeducteePanHelp.Read())
                                {
                                    if (strFormNo == T_FormNo.F24Q)
                                        lstDeducteePANHelp.Items.Add(new ListBoxItem(drdShowDeducteePanHelp[strEmpDed + "_NAME"].ToString().PadRight(58) + drdShowDeducteePanHelp[strEmpDed + "_PAN"].ToString().PadRight(13)));
                                    else
                                        lstDeducteePANHelp.Items.Add(new ListBoxItem(drdShowDeducteePanHelp[strEmpDed + "_NAME"].ToString().PadRight(58) + drdShowDeducteePanHelp[strEmpDed + "_PAN"].ToString().PadRight(13) + drdShowDeducteePanHelp["DEDUCTEE_CODE"]));
                                    //--
                                    //if (lstDeducteePANHelp.Height <= 300)
                                    //    lstDeducteePANHelp.Height = lstDeducteePANHelp.Height + 19;
                                }
                                //--
                                if (lstDeducteePANHelp.Items.Count <= 0)
                                    lstDeducteePANHelp.Visible = false;
                                //--
                                if (TDSMAN.Classes.TDSMAN.T_ShowCompanyWiseDeductee == true && strFormNo != T_FormNo.F24Q)
                                {
                                    lstDeducteePANHelp.Items.Add(new ListBoxItem(strHelpLastLineText));
                                    //if (lstDeducteePANHelp.Height <= 300)
                                    //    lstDeducteePANHelp.Height = lstDeducteePANHelp.Height + 25;
                                }
                                //--
                            }
                            //-----------------------------------------------------------
                            drdShowDeducteePanHelp.Close();
                            drdShowDeducteePanHelp.Dispose();
                        }
                    }
                    //-----------------------------------------------------------
                    // TO CHECK THAT DEDUCTEE EXISTS OF THAT SAME VALID PAN
                    ////if (lstDeducteeHelp.Visible == true) return;
                    //###################
                    if (txtDeducteePAN.Text.Length != 10)
                    {
                        lstPANHelp.Visible = false;
                        return;
                    }
                    if (blnShowPANHelp == false) return;
                    //--
                    //-----------------------
                    strSQLShowHelpDeductee = "SELECT " + strEmpDed + "_ID," +
                        "                            " + strEmpDed + "_NAME " +
                        "                     FROM   MST_" + strEmpDed + " " +
                        "                     WHERE  " + strEmpDed + "_PAN   = '" + cmnService.J_ReplaceQuote(txtDeducteePAN.Text) + "' " +
                        "                     AND    " + strEmpDed + "_NAME <> '" + cmnService.J_ReplaceQuote(txtDeducteeName.Text) + "' ";
