                        }
                        //--
                        drdShowDeducteePAN.Close();
                        drdShowDeducteePAN.Dispose();
                        //--
                        if (lstPANHelp.Items.Count <= 1)
                            lstPANHelp.Visible = false;
                    }
                }
                //
                #region COMMENTED
                ////-- GET LAST PAYMENT AMOUNT & TDS FOR 24Q
                //if (strFormNo == T_FormNo.F24Q)
                //{
                //    strSQL = @"SELECT TOP 1 PAYMENT_AMOUNT
