                //        //--
                //        lblLastPayment.Text = "Last Paid Amount : " + string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))));
                //    }
                //    else
                //        lblLastPayment.Text = "";
                //    //
                //    strSQL = @"SELECT TOP 1 TAX_AMOUNT
                //            FROM   TRN_DEDUCTEE_DETAILS,
                //                TRN_BASIC_INFO,
                //                   MST_EMPLOYEE
