        #region lstPANHelp_Click
        private void lstPANHelp_Click(object sender, EventArgs e)
        {
            if (lstPANHelp.SelectedIndex < 1)
            {
                return;
            }
            //--
            blnShowHelp = false;
            txtDeducteeName.Text = lstPANHelp.Text.Trim();
            blnShowHelp = true;
            //
            lstPANHelp.Visible = false;
            //
            if (cmbDeducteeCode.Visible == true)
                cmbDeducteeCode.Select();
            else
                cmbDDSection.Select();
        }
        #endregion

        #region lstPANHelp_KeyPress
        private void lstPANHelp_KeyPress(object sender, KeyPressEventArgs e)
        {
            if (Convert.ToInt64(e.KeyChar) == 13)
                lstPANHelp_Click(sender, e);
            else if (Convert.ToInt64(e.KeyChar) == 27)
            {
                lstPANHelp.Visible = false;
                if (cmbDeducteeCode.Visible == true)
                    cmbDeducteeCode.Select();
                else
                    cmbDDSection.Select();
            }
        }
        #endregion


