        #region txtCertificateNo_KeyPress
        private void txtCertificateNo_KeyPress(object sender, KeyPressEventArgs e)
        {
            if (Convert.ToInt32(e.KeyChar) == 13)
            {
                if (lstCertificateNoHelp.Visible == true)
                {
                    blnShowCertificateNoHelp = false;
                    lstCertificateNoHelp.Select();
                    blnShowCertificateNoHelp = true;
                    lstCertificateNoHelp.SelectedIndex = 0;
                }
                else
                {
                    //SendKeys.Send("{tab}");
                    if (strFormNo == T_FormNo.F27EQ)
                        txtTotalValueOfPurchase.Select();
                    else if (strFormNo == T_FormNo.F27Q)
                    {
                        // Blocked by Dhrub On 2015-10-30 TO SET FOCUS INTO GROSSING UP INDICATOR
                        //cmbTDSRate.Select();
                        cmbGrossingUpIndicator.Select();
                    }
                    else if (strFormNo == T_FormNo.F26Q)
                    {
                        if (TDSMAN.Classes.TDSMAN.T_EnableReferenceNo == true)
                            txtRefernceNo.Select();
                        else
                            BtnSave.Select();
                    }
                    else
                        BtnSave.Select();
                }
            }
        }
        #endregion

        #region txtCertificateNo_KeyDown
        private void txtCertificateNo_KeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Down || e.KeyCode == Keys.Right)
            {
                if (lstCertificateNoHelp.Visible == true)
                {
                    blnShowCertificateNoHelp = false;
                    lstCertificateNoHelp.Focus();
                    //lstCertificateNoHelp.SelectedIndex = 1;
                    blnShowCertificateNoHelp = true;
                    lstCertificateNoHelp.SelectedIndex = 1;
                }
            }
            if (e.KeyCode == Keys.Escape)
                lstCertificateNoHelp.Visible = false;
            //
        }
        #endregion

