        {
            //if (blnShowCertificateNoHelp == true && lstCertificateNoHelp.Focus() == false)
            //    lstCertificateNoHelp.Visible = false;
            //if (blnShowCertificateNoHelp == true )

            //lstCertificateNoHelp.Visible = false;
            blnShowCertificateNoHelp = true;
