        #region txtCertificateNo_TextChanged
        private void txtCertificateNo_TextChanged(object sender, EventArgs e)
        {
            IDataReader drdShowCertificateHelp = null;
            //--
            try
            {
                if (txtDeducteeName.Text.Trim() == "" || txtDeducteePAN.Text.Trim() == "")
                {
                    lstCertificateNoHelp.Visible = false;
                    return;
                }
                //--
                if (blnShowCertificateNoHelp == false)
                    return;
                //-----------------------
                if (strFormNo == T_FormNo.F24Q)
                    strEmpDed = "EMPLOYEE";
                else
                    strEmpDed = "DEDUCTEE";
                //
                string strSQLShowHelpCertificateNo = @" SELECT TRN_DEDUCTEE_DETAILS.CERTIFICATE_NO, 
                                                        SUM(TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT) AS TOTAL_PAYMENT_AMOUNT
                                                 FROM   MST_" + strEmpDed + @", 
                                                        TRN_DEDUCTEE_DETAILS, 
                                                        TRN_BASIC_INFO 
                                                 WHERE  MST_" + strEmpDed + "." + strEmpDed + @"_ID = TRN_DEDUCTEE_DETAILS.PARTY_ID 
                                                 AND    TRN_BASIC_INFO.BASIC_INFO_ID = TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID 
                                                 AND    TRN_BASIC_INFO.ASST_ID = " + Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)) + @" 
                                                 AND    TRN_BASIC_INFO.COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + @" 
                                                 AND    MST_" + strEmpDed + "." + strEmpDed + "_NAME = '" + cmnService.J_ReplaceQuote(txtDeducteeName.Text.Trim()) + @"' 
                                                 AND    MST_" + strEmpDed + "." + strEmpDed + "_PAN  = '" + cmnService.J_ReplaceQuote(txtDeducteePAN.Text.Trim()) + @"' 
                                                 AND    TRN_DEDUCTEE_DETAILS.CERTIFICATE_NO <> '' ";

                //if (txtCertificateNo.Text != "")
                //    strSQLShowHelpCertificateNo = strSQLShowHelpCertificateNo + " AND TRN_DEDUCTEE_DETAILS.CERTIFICATE_NO LIKE '" + cmnService.J_ReplaceQuote(txtCertificateNo.Text.Trim()) + @"%' ";

                strSQLShowHelpCertificateNo = strSQLShowHelpCertificateNo + @" GROUP BY TRN_DEDUCTEE_DETAILS.CERTIFICATE_NO 
                                                                               ORDER BY SUM(TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT) DESC ";

                drdShowCertificateHelp = dmlService.J_ExecSqlReturnReader(strSQLShowHelpCertificateNo);
                //--
                if (drdShowCertificateHelp == null)
                {
                    lstCertificateNoHelp.Visible = false;
                    return;
                }
                else
                {
                    //--
                    Point controlLoc = this.PointToScreen(txtCertificateNo.Location);
                    lstCertificateNoHelp.Location = new Point(319, controlLoc.Y + 90); //Change Location Base on Scroll. 
                    //--
                    lstCertificateNoHelp.Items.Clear();
                    lstCertificateNoHelp.Height = 29;
                    lstCertificateNoHelp.Visible = true;
                    while (drdShowCertificateHelp.Read())
                    {
                        //--
                        if (lstCertificateNoHelp.Items.Count == 0)
                            lstCertificateNoHelp.Items.Add(strCertificateNoHelpHeader);
                        //--
                        lstCertificateNoHelp.Items.Add(new ListBoxItem(drdShowCertificateHelp["CERTIFICATE_NO"].ToString().PadRight(30 - string.Format("{0:0.00}", Convert.ToDouble(drdShowCertificateHelp["TOTAL_PAYMENT_AMOUNT"])).Length) + string.Format("{0:0.00}", Convert.ToDouble(drdShowCertificateHelp["TOTAL_PAYMENT_AMOUNT"]))));
                        //--
                        if (lstCertificateNoHelp.Height <= 57)
                            lstCertificateNoHelp.Height = lstCertificateNoHelp.Height + 19;
                    }
                    //--
                    if (lstCertificateNoHelp.Items.Count <= 0)
                        lstCertificateNoHelp.Visible = false;
                    //--
                    //if (TDSMAN.Classes.TDSMAN.T_ShowCompanyWiseDeductee == true && strFormNo != T_FormNo.F24Q)
                    //{
                    //    lstDeducteeHelp.Items.Add(new ListBoxItem(strHelpLastLineText));
                    //    if (lstDeducteeHelp.Height <= 300)
                    //        lstDeducteeHelp.Height = lstDeducteeHelp.Height + 25;
                    //}
                    //--
                }
                //-----------------------------------------------------------
                drdShowCertificateHelp.Close();
                drdShowCertificateHelp.Dispose();
                //-----------------------------------------------------------
            }
            catch (Exception err_handler)
            {
                drdShowCertificateHelp.Close();
                drdShowCertificateHelp.Dispose();
                cmnService.J_UserMessage(err_handler.Message);
            }
            //-----------------------
        }
        #endregion

