        #region cmbNonResident_SelectedIndexChanged
        private void cmbNonResident_SelectedIndexChanged(object sender, EventArgs e)
        {
            if (cmbNonResident.Text == T_YES_NO.YES)
            {
                cmbPermanentEstablishment.Enabled = true;
                lblPermanentEstablishment.Enabled = true;
            }
            else
            {
                cmbPermanentEstablishment.Enabled = false;
                lblPermanentEstablishment.Enabled = false;
                cmbPermanentEstablishment.Text = "";
            }
        }
        #endregion

        #region btnSaveF27EQ_Click
        private void btnSaveF27EQ_Click(object sender, EventArgs e)
        {
            strNonResident = ""; strPermanentEstablishment = "";
            //--
            if (Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex) >= T_FinancialYearID.F2017_18ID)
            {
                if (txtDeducteePAN.Text == "PANNOTAVBL" || txtDeducteePAN.Text == "PANAPPLIED" || txtDeducteePAN.Text == "PANINVALID")
                {
                    //--
                    if (cmbNonResident.Text == "")
                    {
                        cmnService.J_UserMessage("In case of non-availability of PAN, Deductee Non Resident - Cannot be Blank");
                        cmbNonResident.Select();
                        return;
                    }
                    //--
                    if (cmbNonResident.Text == T_YES_NO.YES)
                    {
                        if (cmbPermanentEstablishment.Text == "")
                        {
                            cmnService.J_UserMessage("Deductee having Permanent Establishment - Cannot be Blank");
                            cmbPermanentEstablishment.Select();
                            return;
                        }
                    }
                }
            }
            //--
            if (cmbNonResident.Text == T_YES_NO.YES)
                strNonResident = "Y";
            else if (cmbNonResident.Text == T_YES_NO.NO)
                strNonResident = "N";
            //--
            if (cmbPermanentEstablishment.Text == T_YES_NO.YES)
                strPermanentEstablishment = "Y";
            else if (cmbPermanentEstablishment.Text == T_YES_NO.NO)
                strPermanentEstablishment = "N";
            //--
            grpForm27EQ.Visible = false;
            blnShowF27EQ = false;
            //
            Insert_Update_Delete_Data();
            //--
            GC.Collect();
        }
        #endregion

        #region btnForm27EQRemarksFGSave_Click
        private void btnForm27EQRemarksFGSave_Click(object sender, EventArgs e)
        {
            //strForm27EQChallanNo = ""; strForm27EQDate = "";
            //--
            if (cmbRemarks.Text.Trim().Substring(0, 1) == "F" ||
                cmbRemarks.Text.Trim().Substring(0, 1) == "G")
            {
                if (txtForm27EQChallanNo.Text == "")
                {
                    cmnService.J_UserMessage("Challan No. - Cannot be Blank");
                    txtForm27EQChallanNo.Select();
                    return;
                }
                //--
                if (dtService.J_IsBlankDateCheck(ref mskForm27EQDateOfPayment, "Payment Date - Cannot be Blank") == true)
                    return;
                //----------------------------------------------------------
                //-- VALID DATE CHECK
                //----------------------------------------------------------
                if (dtService.J_IsDateValid(mskForm27EQDateOfPayment) == false)
                {
                    cmnService.J_UserMessage("Incorrect Format of the Date of Payment");
                    mskForm27EQDateOfPayment.Select();
                    return;
                }
            }
            //--
            grpForm27EQRemarksFG.Visible = false;
            blnShowF27EQRemFG = false;
            //
            Insert_Update_Delete_Data();
            //--
            GC.Collect();
        }
        #endregion

