        #region btnSaveF27Q_Click
        private void btnSaveF27Q_Click(object sender, EventArgs e)
        {
            //--
            if (Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex) >= T_FinancialYearID.F2016_17ID)
            {
                if ((txtDeducteePAN.Text == "PANNOTAVBL" || txtDeducteePAN.Text == "PANAPPLIED" || txtDeducteePAN.Text == "PANINVALID") &&
                    //(Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) == 15) &&
                    (Convert.ToDouble(txtDeducteeRate.Text) < 20))
                {
                    //--
                    if (txtF27QContactNo.Text == "")
                    {
                        cmnService.J_UserMessage("Contact No. - Cannot be Blank");
                        txtF27QContactNo.Select();
                        return;
                    }
                    // CHECK '^'
                    if (TdsMan.T_DetectCaret(txtF27QContactNo.Text.Trim(), "^") == true)
                    {
                        cmnService.J_UserMessage("Contact No. - '^' not allowed");
                        txtF27QContactNo.Select();
                        return;
                    }
                    //--
                    if (txtF27QEmail.ToString().Trim() != "")
                    {
                        if (TdsMan.T_CheckEmailFormat(txtF27QEmail.Text) == false)
                        {
                            txtF27QEmail.Select();
                            return;
                        }
                    }
                    //--
                    if (txtF27QEmail.Text == "")
                    {
                        cmnService.J_UserMessage("Email id - Cannot be Blank");
                        txtF27QEmail.Select();
                        return;
                    }
                    // CHECK '^'
                    if (TdsMan.T_DetectCaret(txtF27QEmail.Text.Trim(), "^") == true)
                    {
                        cmnService.J_UserMessage("Email id - '^' not allowed");
                        txtF27QEmail.Select();
                        return;
                    }
                    //--
                    if (txtF27QTaxIdentificationNumber.Text == "")
                    {
                        cmnService.J_UserMessage("Tax Identification No. - Cannot be Blank");
                        txtF27QTaxIdentificationNumber.Select();
                        return;
                    }
                    // CHECK '^'
                    if (TdsMan.T_DetectCaret(txtF27QTaxIdentificationNumber.Text.Trim(), "^") == true)
                    {
                        cmnService.J_UserMessage("Tax Identification No. - '^' not allowed");
                        txtF27QTaxIdentificationNumber.Select();
                        return;
                    }
                    //--
                    if (txtF27QDeducteeAddress.Text == "")
                    {
                        cmnService.J_UserMessage("Address - Cannot be Blank");
                        txtF27QDeducteeAddress.Select();
                        return;
                    }
                    // CHECK '^'
                    if (TdsMan.T_DetectCaret(txtF27QDeducteeAddress.Text.Trim(), "^") == true)
                    {
                        cmnService.J_UserMessage("Address - '^' not allowed");
                        txtF27QDeducteeAddress.Select();
                        return;
                    }

                }
            }
            //--
            strDeducteeForm27QEmailId = txtF27QEmail.Text;
            strDeducteeForm27QContactNo = txtF27QContactNo.Text;
            strDeducteeForm27QTaxId = txtF27QTaxIdentificationNumber.Text;
            strDeducteeForm27QAddress = txtF27QDeducteeAddress.Text;
            //--
            grpForm27Q.Visible = false;
            //
            blnShowF27Q = false;
            //
            Insert_Update_Delete_Data();
            //--
            GC.Collect();
        }
        #endregion

