        #region lnkUploadAadhaar_LinkClicked
        private void lnkUploadAadhaar_LinkClicked(object sender, LinkLabelLinkClickedEventArgs e)
        {
            //System.Diagnostics.Process.Start("https://incometaxindiaefiling.gov.in/e-Filing/UserLogin/LoginHome.html?lang=eng");
            //MstUploadReturnAadhaar MstUploadReturnAadhaar = new MstUploadReturnAadhaar();
            //MstUploadReturnAadhaar.ShowDialog();
            //TrnFVUSubmissionAadhaar TrnFVUSubmissionAadhaar = new TrnFVUSubmissionAadhaar();
            //TrnFVUSubmissionAadhaar.Text = "Upload TDS using Aadhaar (using OTP)";
            //TrnFVUSubmissionAadhaar.MdiParent = TrnRegularReturn.ActiveForm;
            //TrnFVUSubmissionAadhaar.Show();
            string strFVUVersion = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT FVU_VERSION FROM MST_ASSESSMENT WHERE ASST_ID = " + Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex))));
            TDSMAN.Classes.TDSMAN.T_FVUVersionOnlineFilling = "FVU " + strFVUVersion;
            TDSMAN.Classes.TDSMAN.T_FAYearOnlineFilling = cmbFinancialYear.Text;
            TDSMAN.Classes.TDSMAN.T_FormNoOnlineFilling = strFormNo;
            TDSMAN.Classes.TDSMAN.T_QtrOnlineFilling = cmbQuarter.Text;
            TDSMAN.Classes.TDSMAN.T_UploadTypeOnlineFilling = "R";
            //--
            strSQL = "SELECT OUTPUT_FILE_PATH + '\\' + LEFT(INPUT_FILE_NAME,7) AS FILE_PATH FROM TRN_FILE_GENERATION_LOG WHERE BASIC_INFO_ID = " + lngBasicInfoID + " ORDER BY FG_LOG_ID DESC";
            string strOutputFilePath = Convert.ToString(dmlService.J_ExecSqlReturnScalar(dmlService.J_pCommand, strSQL));
            //
            strFVUZIPFile = Path.ChangeExtension(strOutputFilePath, ".ZIP");
            TDSMAN.Classes.TDSMAN.T_UploadFilePath = strFVUZIPFile;
            //--
            strSQL = "SELECT USER_PASSWORD FROM MST_TAN_AADHAAR WHERE TAN_NO ='" + txtTAN.Text.Trim() + "'";
            if (Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)).Trim() != "")
            {
                //--
                TDSMAN.Classes.TDSMAN.T_TANOnlineFilling = txtTAN.Text.Trim();
                TDSMAN.Classes.TDSMAN.T_PasswordOnlineFilling = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)).Trim();
                //--
                if (cmnService.J_UserMessage("This will take you to 'incometaxindiaefiling.gov.in' webpage, where you have to enter the captcha for login, for any query regarding the\n contents of the linked page please contact the concerned website.", MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.No)
                    return;
                //--
                TrnUploadTDSBrowser TrnUploadTDSBrowser = new TrnUploadTDSBrowser();
                TrnUploadTDSBrowser.MdiParent = TrnRegularReturn.ActiveForm;
                TrnUploadTDSBrowser.Show();
                //TrnUploadTDSBrowser.ShowDialog();
                //--
            }
            else
            {
                TDSMAN.Classes.TDSMAN.T_TANOnlineFilling = txtTAN.Text.Trim();
                //--
                //TrnFVUSubmissionAadhaar TrnFVUSubmissionAadhaar = new TrnFVUSubmissionAadhaar();
                //TrnFVUSubmissionAadhaar.Text = "Upload TDS using Aadhaar (using OTP)";
                //TrnFVUSubmissionAadhaar.MdiParent = TrnRegularReturn.ActiveForm;
                //TrnFVUSubmissionAadhaar.Show();
                //-- 2023/01/11
                TrnUploadFVU TrnUploadFVU = new TrnUploadFVU();
                TrnUploadFVU.Text = "Upload TDS using Aadhaar (using OTP)";
                TrnUploadFVU.MdiParent = TrnRegularReturn.ActiveForm;
                TrnUploadFVU.Show();
                //TrnFVUSubmissionAadhaar.ShowDialog();
            }
        }
        #endregion

        #region lnkTINFCCharges_LinkClicked
        private void lnkTINFCCharges_LinkClicked(object sender, LinkLabelLinkClickedEventArgs e)
        {
            long lngTotSDRecords = 0;
            if (strFormNo == T_FormNo.F24Q && cmbQuarter.Text == T_Qtr.Q4)
            {
                lngTotSDRecords = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(SALARY_DETAILS_ID) AS COUNT_SALARY_DETAIL_ID FROM TRN_SALARY_DETAILS WHERE BASIC_INFO_ID = " + lngBasicInfoID)));
            }
            //--
            if ((cmnService.J_ReturnInt32Value(txtTotalDeducteeRecords.Text.Trim()) + lngTotSDRecords) <= 100)
            {
                cmnService.J_UserMessage("TIN-FC upload charges (inclusive of GST) : 50 INR");
            }
            else if ((cmnService.J_ReturnInt32Value(txtTotalDeducteeRecords.Text.Trim()) + lngTotSDRecords) <= 1000)
            {
                cmnService.J_UserMessage("TIN-FC upload charges (inclusive of GST) : 210 INR");
            }
            else
            {
                cmnService.J_UserMessage("TIN-FC upload charges (inclusive of GST) : 683 INR");
            }
        }
        #endregion



        #region pctUserManual_Click
        private void pctUserManual_Click(object sender, EventArgs e)
        {
            if (lblSearchMode.Text == Tabbed_Mode.Basic)
            {
                if (grpGenerateReturns.Visible == true)
                {
                    TDSMAN_WEB.Registration Registration = new TDSMAN.TDSMAN_WEB.Registration();
                    System.Diagnostics.Process.Start(Registration.GetYoutubeLink("M0025", TdsMan.GetSerialNo(), TDSMAN.Classes.TDSMAN.T_pVersionType.ToString(), ""));
                }
                else if (OrphanEntry == T_DEDUCTEE_FIRST_MODULES.DEDUCTEE) //-- 2024/03/28
                {
                    TDSMAN_WEB.Registration Registration = new TDSMAN.TDSMAN_WEB.Registration();
                    System.Diagnostics.Process.Start(Registration.GetYoutubeLink("M0124", TdsMan.GetSerialNo(), TDSMAN.Classes.TDSMAN.T_pVersionType.ToString(), ""));
                }
                else
                {
                    TDSMAN_WEB.Registration Registration = new TDSMAN.TDSMAN_WEB.Registration();
                    System.Diagnostics.Process.Start(Registration.GetYoutubeLink("M0023", TdsMan.GetSerialNo(), TDSMAN.Classes.TDSMAN.T_pVersionType.ToString(), ""));
                }
            }
            else if (lblSearchMode.Text == Tabbed_Mode.Challan || lblSearchMode.Text == Tabbed_Mode.Deductee)
            {
                TDSMAN_WEB.Registration Registration = new TDSMAN.TDSMAN_WEB.Registration();
                System.Diagnostics.Process.Start(Registration.GetYoutubeLink("M0024", TdsMan.GetSerialNo(), TDSMAN.Classes.TDSMAN.T_pVersionType.ToString(), ""));
            }
        }

