        private void lstDeducteePANHelp_KeyPress(object sender, KeyPressEventArgs e)
        {
            if (Convert.ToInt64(e.KeyChar) == 13)
                lstDeducteePANHelp_Click(sender, e);
            else if (Convert.ToInt64(e.KeyChar) == 27)
