        #region InsertCompanyBasicInfo
        private void InsertCompanyBasicInfo(long CompanyId, long BasicInfoId)
        {
            //-----------------------------------------------------------
            strSQL = "INSERT INTO TRN_COMPANY_INFO (" +
                     "            BASIC_INFO_ID," +
                     "            COMPANY_ID," +
                     "            GROUP_ID," +
                     "            TAN_NO," +
                     "            PAN_NO," +
                     "            COMPANY_NAME," +
                     "            BRANCH_DIV," +
                     "            D_CATEGORY_ID," +
                     "            MINISTRY_ID," +
                     "            MINISTRY_OTHER," +
                     "            ADDRESS1," +
                     "            ADDRESS2," +
                     "            ADDRESS3," +
                     "            ADDRESS4," +
                     "            ADDRESS5," +
                     "            STATE_ID," +
                     "            PIN_CODE," +
                     "            STD," +
                     "            PHONE," +
                     "            EMAIL," +
                     "            PERSON_NAME," +
                     "            DESIGNATION," +
                     "            FATHER_NAME," +
                     "            P_ADDRESS1," +
                     "            P_ADDRESS2," +
                     "            P_ADDRESS3," +
                     "            P_ADDRESS4," +
                     "            P_ADDRESS5," +
                     "            P_STATE_ID," +
                     "            P_PIN_CODE," +
                     "            P_STD," +
                     "            P_PHONE," +
                     "            P_EMAIL," +
                     "            P_MOBILE," +
                     "            PAO_CODE," +
                     "            PAO_REG_NO," +
                     "            DDO_CODE," +
                     "            DDO_REG_NO," +
                     "            D_STATE_ID," +
                     "            AIN_NO," +
                     "            TAN_REG_NO," +
                     "            ALT_STD," +
                     "            ALT_PHONE," +
                     "            ALT_EMAIL," +
                     "            P_ALT_STD," +
                     "            P_ALT_PHONE," +
                     "            P_ALT_EMAIL," +
                     "            P_PAN," +
                     "            GSTN," +
                     "            SECTION_194P_FLAG) " +
                     "     VALUES( " + BasicInfoId + "," +
                     "             " + CompanyId + "," +
                     "             " + TDSMAN.Classes.TDSMAN.T_pGroupId + "," +
                     "            '" + cmnService.J_ReplaceQuote(txtTANNo.Text.Trim()) + "'," +
                     "            '" + cmnService.J_ReplaceQuote(txtPANNo.Text.Trim()) + "'," +
