               "             MST_COMPANY.SECTION_194P_FLAG     AS SECTION_194P_FLAG " +
               "     FROM    (((((MST_COMPANY INNER JOIN MST_CATEGORY " +
               "             ON MST_COMPANY.D_CATEGORY_ID     = MST_CATEGORY.CATEGORY_ID) " +
