                                txtDeducteeSrlNo.Text = Convert.ToString(dmlService.J_ReturnMaxValue("TRN_DEDUCTEE_DETAILS", "SL_NO", "CHALLAN_ID = 0 AND BASIC_INFO_ID = " + lngBasicInfoID + "") + 1);
                                txtViewDeducteeTotalTaxDeposited.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(TAX_DEPOSITED_AMOUNT) AS TAX_DEPOSITED_AMOUNT FROM TRN_DEDUCTEE_DETAILS WHERE CHALLAN_ID = 0 AND BASIC_INFO_ID = " + lngBasicInfoID)) == "" ? "0" : Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(TAX_DEPOSITED_AMOUNT) AS TAX_DEPOSITED_AMOUNT FROM TRN_DEDUCTEE_DETAILS WHERE CHALLAN_ID = 0 AND BASIC_INFO_ID = " + lngBasicInfoID))));
