        #region LoadDeducteeGrid

        #region LoadDeducteeGrid
        private void LoadDeducteeGrid(long ChallanDetailID, long BasicInfoID)
        {
            //-- 2020/06/03
            string strSQLColumn = "", strGridColumn = "";
            string[,] strLoadSectionMatrix = {{"SECTION_NAME_2 <> ''", "F", "SECTION_NO + ' [' + SECTION_NAME_2 + ']'", "F"},
                                        {"SECTION_NAME_2 = ''", "F", "", "T"}};
            //
            if (strFormNo == T_FormNo.F24Q && TDSMAN.Classes.TDSMAN.T_ShareReferenceNoF24Q == true)
            {
                strGridColumn = "Ref No";
                strSQLColumn = "MST_" + strEmpDed + ".EMPLOYEE_REF AS EMPLOYEE_REF,";
            }
            else
            {
                strGridColumn = "Section";
                strSQLColumn = "";
                //strSQLColumn = "MST_SECTION.SECTION_NO AS SECTION_NO,";
                //strLoadSectionMatrix = {{"SECTION_NAME_2 <> ''", "F", "SECTION_NO + ' [' + SECTION_NAME_2 + ']'", "F"},
                //                        {"SECTION_NAME_2 = ''", "F", "", "T"}};
            }
            //-----------------------------------------------------------
            //string[,] strMatrixDeducteeDetails = {{"DeducteeDetailsID", "0", "", "Right", "", "", ""},
            //                            {"Challan Srl No.", "100", "S", "", "", "", ""},
            //                            {"Srl No.", "100", "S", "", "", "", ""},
            //                            {"PAN", "100", "S", "", "", "", ""},
            //                            {"Name", "250", "S", "", "", "", ""},
            //                            {"Date", "100", "dd/MM/yyyy", "", "", "", ""},
            //                            {"Section", strSectionSize, "S", "", "", "", ""},
            //                            {"Amount Paid", "100", "0.00", "R", "", "", "T"},
            //                            {"Total TDS", "100", "0.00", "R", "", "", "T"},
            //                            {"TDS Deposited", "100", "0.00", "R", "", "", "T"},
            //                            {"Certificate No.", "70", "0.00", "R", "", "", "T"}};

            string[,] strMatrixViewDeductee = {{"DEDUCTEE_DETAIL_ID", "0", "", "", "", "F", ""},
                                        {"Sl.", "38", "", "", "", "", ""},
                                        {"Deductee_ID", "0", "", "", "", "F", ""},
                                        {"PAN No", "75", "S", "", "", "", ""},
                                        {"Party Name", "110", "S", "", "", "", "T"},
                                        //{"Section", "44", "S", "", "", "", ""},
                                        {strGridColumn, "44", "S", "", "", "", "T"},
                                        {"Amount", "75", "0.00", "R", "", "", "T"},
                                        {"Date", "68", "dd/MM/yyyy", "", "", "", "T"},
                                        {"Total", "85", "0.00", "R", "", "", "T"},
                                        {"Tax Deposited", "85", "0.00", "R", "", "", "T"}};
            //-----------------------------------------------------------
            //strMatrix = strMatrix1;
            //-----------------------------------------------------------
            /* (1) Column Value
             * (2) Column Data Type
             * (3) Replace String
             * (4) Replace String Data Type */
            //-----------------------------------------------------------
            //-----------------------------------------------------------
            strOrderBy = "TRN_DEDUCTEE_DETAILS.SL_NO";
            strQuery = "SELECT TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID   AS DEDUCTEE_DETAIL_ID," +
                     "         TRN_DEDUCTEE_DETAILS.SL_NO                AS SL_NO," +
                     "         MST_" + strEmpDed + "." + strEmpDed + "_ID   AS DEDUCTEE_ID," +
                     "         MST_" + strEmpDed + "." + strEmpDed + "_PAN  AS DEDUCTEE_PAN," +
                     "         MST_" + strEmpDed + "." + strEmpDed + "_NAME AS DEDUCTEE_NAME,";
            //"         MST_SECTION.SECTION_NO                    AS SECTION_NO," +
            if (strSQLColumn == "")
                strQuery = strQuery + cmnService.J_SQLDBFormat(strLoadSectionMatrix, J_SQLColFormat.Case_End) + " AS SECTION_NO,";
            else
                strQuery = strQuery + strSQLColumn;
            strQuery = strQuery + @" TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT       AS PAYMENT_AMOUNT," +
                     "         TRN_DEDUCTEE_DETAILS.PAYMENT_DATE         AS PAYMENT_DATE," +
                     "         TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT         AS TOTAL_AMOUNT," +
                     "         TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT AS TAX_DEPOSITED_AMOUNT " +
                     "  FROM   TRN_DEDUCTEE_DETAILS," +
                     "         MST_" + strEmpDed + "," +
                     "         MST_SECTION " +
                     "  WHERE  TRN_DEDUCTEE_DETAILS.PARTY_ID      = MST_" + strEmpDed + "." + strEmpDed + "_ID " +
                     "  AND    TRN_DEDUCTEE_DETAILS.SECTION_ID    = MST_SECTION.SECTION_ID " +
                     "  AND    TRN_DEDUCTEE_DETAILS.CHALLAN_ID    = " + ChallanDetailID + " " +
                     "  AND    TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = " + BasicInfoID + " ";
            //-----------------------------------------------------------
            strSQL = strQuery + " ORDER BY " + strOrderBy;
            //-----------------------------------------------------------
            if (dsetGridClone != null) dsetGridClone.Clear();
            //dsetGridClone = dmlService.J_ShowDataInGrid(ref  dgcViewDeductee, strSQLGridViewTabPages, strMatrixViewDeductee);       //Show Data into the Grid                
            dsetGridClone = dmlService.J_ShowDataInGrid(ref dgcViewDeductee, strSQL, strMatrixViewDeductee);       //Show Data into the Grid                
        }
