                        {
                            strSQL = "UPDATE TRN_SALARY_DETAILS SET AIS_Total = AIS_ITEM_1 + AIS_ITEM_2 WHERE BASIC_INFO_ID = " + lngBasicInfoID;
                            dmlService.J_ExecSql(strSQL);
                            //
                            //-- 2024/03/14
                            if (Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)) >= T_FinancialYearID.F2023_24ID)
                            {
                                strGrossTotalIncome = string.Format("{0:0.00}", cmnService.J_ReturnDoubleValue(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM((((TS_GS_SEC_17_1 + TS_GS_SEC_17_2 + TS_GS_SEC_17_3 + REPORTED_TAXABLE_AMOUNT) - (US_16_AGGREGATE + SEC10_TOTAL_AMOUNT)) + (AIS_Total))) AS SUM_GROSS_TOTAL_INCOME FROM TRN_SALARY_DETAILS WHERE BASIC_INFO_ID = " + lngBasicInfoID + " "))));
                            }
