                            {
                                strGrossTotalIncome = string.Format("{0:0.00}", cmnService.J_ReturnDoubleValue(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM((((TS_GS_SEC_17_1 + TS_GS_SEC_17_2 + TS_GS_SEC_17_3 + REPORTED_TAXABLE_AMOUNT) - (US_16_AGGREGATE + SEC10_TOTAL_AMOUNT)) + (AIS_Total))) AS SUM_GROSS_TOTAL_INCOME FROM TRN_SALARY_DETAILS WHERE BASIC_INFO_ID = " + lngBasicInfoID + " AND SECTION_115BAC_FLAG = 0 "))));
                                strGrossTotalIncome = string.Format("{0:0.00}", cmnService.J_ReturnDoubleValue(strGrossTotalIncome) + cmnService.J_ReturnDoubleValue(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM((((TS_GS_SEC_17_1 + TS_GS_SEC_17_2 + TS_GS_SEC_17_3 + REPORTED_TAXABLE_AMOUNT) - (SEC10_TOTAL_AMOUNT)) + (AIS_Total))) AS SUM_GROSS_TOTAL_INCOME FROM TRN_SALARY_DETAILS WHERE BASIC_INFO_ID = " + lngBasicInfoID + " AND SECTION_115BAC_FLAG = 1"))));
                            }
                        }
