                        strGrossTotalIncome194P = string.Format("{0:0.00}", cmnService.J_ReturnDoubleValue(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(GROSS_TOTAL_INCOME) AS SUM_GROSS_TOTAL_INCOME FROM TRN_SALARY_DETAILS_194P WHERE BASIC_INFO_ID = " + lngBasicInfoID))));
