        #region DownloadCSIFile(notinuse)
        private bool DownloadCSIFile()
        {
            //int err = 1;
            int iC = 0;
            try
            {
                strCSIFileDownloadFileMessage = "";
                //string url = @"http://www.thereforesystems.com/wp-content/uploads/2008/08/image35.png";

                //// Create an instance of WebClient
                //WebClient client = new WebClient();

                //// Hookup DownloadFileCompleted Event
                ////client.DownloadFileCompleted +=
                ////    new AsyncCompletedEventHandler(client_DownloadFileCompleted);

                //// Start the download and copy the file to c:\temp
                //client.DownloadFileAsync(new Uri(url), @"c:\temp\image35.png");
                CSI_DOWNLOAD:
                strCSIDownloadFilePath = Path.Combine(Path.GetDirectoryName(txtTextFilePath.Text), txtTAN.Text + string.Format("{0:ddMMyy}", System.DateTime.Now.Date)) + ".csi";
                if (File.Exists(strCSIDownloadFilePath) == true)
                    File.Delete(strCSIDownloadFilePath);
                //
                if (chkCSIFileDownload.Checked == false)
                    return false;
                //
                mskViewCSIFileDownloadFrom.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT MIN(DEPOSIT_DATE) AS MIN_DEPOSIT_DATE FROM TRN_CHALLAN WHERE BASIC_INFO_ID = " + lngBasicInfoID));
                mskViewCSIFileDownloadTo.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT MAX(DEPOSIT_DATE) AS MAX_DEPOSIT_DATE FROM TRN_CHALLAN WHERE BASIC_INFO_ID = " + lngBasicInfoID));
                //
                string url = "https://tin.tin.nsdl.com/oltas/servlet/TanSearch/?appUser=T&TAN_NO=" + txtTAN.Text +
                              "&TAN_FROM_DT_DD=" + cmnService.J_Left(mskViewCSIFileDownloadFrom.Text, 2) +
                              "&TAN_FROM_DT_MM=" + cmnService.J_Mid(mskViewCSIFileDownloadFrom.Text, 3, 2) +
                              "&TAN_FROM_DT_YY=" + cmnService.J_Right(mskViewCSIFileDownloadFrom.Text, 4) +
                              "&TAN_TO_DT_DD=" + cmnService.J_Left(mskViewCSIFileDownloadTo.Text, 2) +
                              "&TAN_TO_DT_MM=" + cmnService.J_Mid(mskViewCSIFileDownloadTo.Text, 3, 2) +
                              "&TAN_TO_DT_YY=" + cmnService.J_Right(mskViewCSIFileDownloadTo.Text, 4) +
                              "&submit=Download Challan file";

                WebClient client = new WebClient();
                //strCSIDownloadFilePath = "@" + txtViewInputPath.Text + "\\" + txtViewTAN.Text + Convert.ToString(System.DateTime.Now) + ".csi";
                //string url = "https://tin.tin.nsdl.com/oltas/servlet/TanSearch/?appUser=T&TAN_NO=CALB01678F&TAN_FROM_DT_DD=01&TAN_FROM_DT_MM=01&TAN_FROM_DT_YY=2010&TAN_TO_DT_DD=01&TAN_TO_DT_MM=04&TAN_TO_DT_YY=2010&submit=Download Challan file";
                //client.DownloadFileAsync(new Uri(url), @"c:\" + txtViewTAN.Text);
                //client.DownloadDataAsync(new Uri(url), @"" + strCSIDownloadFilePath);
                client.DownloadFileAsync(new Uri(url), @"" + strCSIDownloadFilePath); //-- ANIK 2016/01/11
                client.Dispose();
                //
                //--
                long lngTimeOut = 0;
                for (int i = 0; i <= 2; i++)
                {
                    // GET FILE SIZE
                    FileInfo fInfo = new FileInfo(@"" + strCSIDownloadFilePath);
                    long size = fInfo.Length;
                    //
                    fInfo.Refresh();
                    //
                    if (size > 0)
                        goto CHECK_FILE;
                    //
                    lngTimeOut = lngTimeOut + 1;
                    //
                    if (lngTimeOut > 152912)
                        goto CHECK_FILE;

                    i = 0;
                    i++;
                }
                //--
                CHECK_FILE:
                for (int i = iC; i <= 3; i++)
                {
                    iC = iC + 1;
                    //
                    if (iC == 3)
                    {
                        strCSIFileDownloadFileMessage = "Some error occurred while downloading CSI.\n Please try after some time.";
                        return false;
                    }
                    //
                    //err = 1;
                    System.Threading.Thread.Sleep(3000);
                    //
                    string text = System.IO.File.ReadAllText(@"" + strCSIDownloadFilePath);
                    //string text;
                    //using (StreamReader streamReader = new StreamReader(strCSIDownloadFilePath))
                    //{
                    //    text = streamReader.ReadToEnd();
                    //}
                    //System.IO.StreamReader myFile = new System.IO.StreamReader(strCSIDownloadFilePath);
                    //string text = myFile.ReadToEnd();
                    //err = 2;
                    if (text.Contains("<HTML>") == true)
                    {
                        if (text.ToUpper().Contains("PLEASE ENTER VALID TAN") == true)
                        {
                            //text = "";
                            strCSIFileDownloadFileMessage = "No CSI file was downloaded as the TAN number provided for the company is invalid.\nPlease correct the TAN number and try again.";
                            return false;
                        }
                        else if (text.ToUpper().Contains("RECORD NOT FOUND") == true)
                        {
                            //text = "";
                            //strCSIFileDownloadFileMessage = "No Challans were found for downloading CSI file.\nPlease check the challan dates specified and try again.";
                            strCSIFileDownloadFileMessage = "CSI file was not downloaded.\n\nPlease check the following:\n1. All Challan records in the return have correct values.\n2. NSDL website 'www.tin-nsdl.com' is working.";
                            return false;
                        }
                        else
                        {
                            //text = "";
                            goto CSI_DOWNLOAD;
                        }
                    }
                    else if (text == "")
                    {
                        //strCSIFileDownloadFileMessage = "Some unexpected error occurred.\nBlank CSI file was downloaded.";
                        strCSIFileDownloadFileMessage = "CSI downloaded does not contain any record. Please check whether all Challan records in the return have correct values.\n\nYou can also manually download the CSI file by visiting NSDL website 'www.tin-nsdl.com'.1" + text;
                        return false;
                    }
                    else
                        return true;
                }
                //--
                return true;
            }
            catch (Exception err_handler)
            {
                //cmnService.J_UserMessage(err_handler.Message + err);
                //strCSIFileDownloadFileMessage = "No CSI file was downloaded as the TAN number provided for the company is invalid.\nPlease correct the TAN number and try again.";
                //strCSIFileDownloadFileMessage = "Some unexpected error occurred.\nBlank CSI file was downloaded."; 
                strCSIFileDownloadFileMessage = "CSI downloaded does not contain any record. Please check whether all Challan records in the return have correct values.\n\nYou can also manually download the CSI file by visiting NSDL website 'www.tin-nsdl.com'.";
                return false;
            }
        }
