        #region ShowRate
        private void ShowRate()
        {
            // Added by Shrey Kejriwal on 11/02/2014
            // Not showing rate when data is getting populated for edit mode
            if (blnShowPANHelp == false)
                return;
            if (txtCertificateNo.Text != "")
                return;
            //------------------------------------------
            //CHECKING FOR MST_PREFERENCES 
            //------------------------------------------
            if (TDSMAN.Classes.TDSMAN.T_ShowNonSalaryTDSRate == true)
            {
                //-------------------------------
                //---Initialize the Section Id
                //-------------------------------
                int intSectionId = 0;
                //if (Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex) >= T_FinancialYearID.F2013_14ID)
                //if (Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex) >= T_FinancialYearID.F2010_11ID)
                //{
                //strSectionNo = cmbDDSection.Text.ToString();if (cmbDDSection.SelectedIndex >= 0)
                intSectionId = Convert.ToInt32(Support.GetItemData(cmbDDSection, cmbDDSection.SelectedIndex));
                //}
                //else
                //{
                //    //strSectionNo = txtViewChallanDetailsSection.Text.ToString();
                //    //if (lblViewChallanDetailsSectionId.Text != "")
                //    //    intSectionId = Convert.ToInt32(lblViewChallanDetailsSectionId.Text);
                //}
                //---------------------------------
                //FETCHING TDS RATE FOR NONSALARY 
                //---------------------------------
                int intIgnoreTaxRate = 0;
                int intComplianceHigherRateFlag = 0;
                //
                errComplianceHigherRateFlag.Clear();
                if (TdsMan.CalcTDSRateForNonSalary(dmlService.J_pCommand, intSectionId, mskDeducteeDate.Text, txtDeducteePAN.Text, strFormNo, out intIgnoreTaxRate, out intComplianceHigherRateFlag) > 0)
                {
                    //-- 2020/10/13
                    if (intIgnoreTaxRate == 1)
                    {
                        if (cmbDDSection.Text == "194NF")
                        {
                            if (txtDeducteePAN.Text == "PANNOTAVBL")
                            {
                                txtDeducteeRate.Text = "20.0000";
                            }
                            else
                            {
                                if (rbn194N20L1Cr.Checked == true)
                                {
                                    txtDeducteeRate.Text = "2.0000";
                                }
                                else if (rbn194NGreater1Cr.Checked == true)
                                {
                                    txtDeducteeRate.Text = "5.0000";
                                }
                            }
                        }
                        else if (cmbDDSection.Text == "194N-FT") //--2023/08/14
                        {
                            if (txtDeducteePAN.Text == "PANNOTAVBL")
                            {
                                txtDeducteeRate.Text = "20.0000";
                            }
                            else
                            {
                                if (rbn194NFT20L3Cr.Checked == true)
                                {
                                    txtDeducteeRate.Text = "2.0000";
                                }
                                else if (rbn194NFTExcess3Cr.Checked == true)
                                {
                                    txtDeducteeRate.Text = "5.0000";
                                }
                            }
                        }
                        //-- 2023/08/14 FVU 8.2

                    }
                    else
                        txtDeducteeRate.Text = string.Format("{0:0.0000}", TDSMAN.Classes.TDSMAN.T_NonSalaryTDSRate);
                    //-- 2021/06/22
                    //if (Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex) >= T_FinancialYearID.F2021_22ID)
                    //{
                    //    if (Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex) == T_FinancialYearID.F2021_22ID
                    //       && Convert.ToInt16(cmnService.J_Right(cmbQuarter.Text, 1)) == Convert.ToInt16(cmnService.J_Right(T_Qtr.Q1, 1)))
                    //    {
                    //        errComplianceHigherRateFlag.Clear();
                    //    }
                    //    else
                    //    {
                    if (intComplianceHigherRateFlag > 0 && Convert.ToDouble(txtDeducteeRate.Text) > 0)
                    {
                        //errComplianceHigherRateFlag.SetError(txtDeducteeRate, "Compliance Check for Sections 206AB & 206CCA");
                        if (strFormNo == T_FormNo.F27EQ)
                            errComplianceHigherRateFlag.SetError(txtDeducteeRate, "Higher Rate - Section 206CCA");
                        else
                            errComplianceHigherRateFlag.SetError(txtDeducteeRate, "Higher Rate - Section 206AB");
                    }
                    else
                        errComplianceHigherRateFlag.Clear();
                    //    }
                    //}
                    //else
                    //    errComplianceHigherRateFlag.Clear();
                }
                else
                    txtDeducteeRate.Text = "0.0000";
            }
        }
