        #region LoadRemittanceBasedOnSection
        private void LoadRemittanceBasedOnSection(long SectionID)
        {
            if(SectionID > 0)
            {
                strSQL = @"SELECT MST_REMITTANCE.REMITTANCE_ID,
                                  MST_REMITTANCE.REMITTANCE_DESC + ' ' + MST_REMITTANCE.REMITTANCE_CODE 
                           FROM   MST_REMITTANCE, 
                                  MST_SECTION_REMITTANCE
                           WHERE  MST_REMITTANCE.REMITTANCE_ID = MST_SECTION_REMITTANCE.REMITTANCE_ID
                           AND    MST_SECTION_REMITTANCE.SECTION_ID = " + SectionID + @"
                           AND    MST_REMITTANCE.INACTIVE_FLAG = 0 
                           AND    MST_REMITTANCE.ASST_ID <= " + Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex) + @" 
                           AND   (MST_REMITTANCE.VALID_UPTO_ASST_ID >= " + Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex) + @" OR MST_REMITTANCE.VALID_UPTO_ASST_ID = 0)
                           ORDER BY MST_REMITTANCE.REMITTANCE_CODE";
                if (dmlService.J_PopulateComboBox(strSQL, ref cmbRemittance) == false) return;
                //--
            }
            //else
            //{
            //    strSQL = @"SELECT MST_REMITTANCE.REMITTANCE_ID,
            //                      MST_REMITTANCE.REMITTANCE_DESC + ' ' + MST_REMITTANCE.REMITTANCE_CODE 
            //               FROM   MST_REMITTANCE
            //               WHERE  1=2 AND ORDER BY MST_REMITTANCE.REMITTANCE_CODE";
            //    if (dmlService.J_PopulateComboBox(strSQL, ref cmbRemittance) == false) return;
            //}
        }
        #endregion

