        #region LoadSections
        private void LoadSections(string FormNo, ref ComboBox combobox)
        {
            LoadSections(FormNo, ref combobox);
        }
        #endregion

        #region LoadSections
        private void LoadSections(string FormNo, ref ComboBox combobox, string Conditions)
        {
            //-----------
            //-- SECTION
            //-----------
            strSQL = " SELECT SECTION_ID," +
                "             SECTION_NO " +
                "      FROM   MST_SECTION " +
                "      WHERE  FORM_NAME = '" + FormNo + "' " + Conditions +
                //"      ORDER BY SECTION_ID";
                "      ORDER BY SECTION_NO";
            if (dmlService.J_PopulateComboBox(strSQL, ref combobox) == false) return;
            //-----------
        }
        #endregion


        #region LoadSections
        //-- 2026/03/23 for loading section based on fa_year
        private void LoadSections(string FormNo, ref ComboBox combobox, long ValidASST_ID, string Conditions)
        {
            string[,] strLoadSectionMatrix = {{"SECTION_NAME_2 <> ''", "F", "SECTION_NO + ' [' + SECTION_NAME_2 + ']'", "F"},
                                              {"SECTION_NAME_2 = ''", "F", "", "T"}};
            //-----------
            //-- SECTION
            //-----------
            strSQL = " SELECT SECTION_ID," +
                //"             SECTION_NO " +
                "       " + cmnService.J_SQLDBFormat(strLoadSectionMatrix, J_SQLColFormat.Case_End) + " AS SECTION_NO " +
                "      FROM   MST_SECTION " +
                "      WHERE  FORM_NAME = '" + FormNo + "' " + Conditions +
                "      AND ASST_ID <= " + ValidASST_ID + " " +
                "      AND (VALID_UPTO_ASST_ID >= " + ValidASST_ID + " OR VALID_UPTO_ASST_ID = 0) " +
                "      ORDER BY SECTION_NAME_2, SECTION_NO";
            if (dmlService.J_PopulateComboBox(strSQL, ref combobox) == false) return;
            //-----------
        }
        #endregion



        #region LoadMinorHead
        private void LoadMinorHead(ref ComboBox combobox)
        {
            strSQL = " SELECT MINOR_HEAD_ID," +
                 "             MINOR_HEAD_CODE + '-' + MINOR_HEAD_DESC AS MINOR " +
                 "      FROM   MST_MINOR_HEAD " +
                 "      ORDER BY MINOR_HEAD_ID";
            if (dmlService.J_PopulateComboBox(strSQL, ref combobox) == false) return;
            //--
            if (lblMode.Text.ToUpper() == "ADD MODE")
            {
                if (TDSMAN.Classes.TDSMAN.T_DEFAULT_MINOR_CODE != "")
                    combobox.Text = TDSMAN.Classes.TDSMAN.T_DEFAULT_MINOR_CODE;
            }
            //--
        }
        #endregion

