        #region SAVE_RP_PAN
        private void SAVE_RP_PAN()
        {
            //-- UPDATE MST_COMPANY
            strSQL = @"UPDATE MST_COMPANY 
                       SET    P_PAN       ='" + cmnService.J_ReplaceQuote(txtRPPAN.Text) + @"' 
                       WHERE  PERSON_NAME ='" + cmnService.J_ReplaceQuote(txtResponsiblePersonName.Text.Trim()) + @"'
                       AND    COMPANY_ID  = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex));
            dmlService.J_ExecSql(strSQL);
            //-- UPDATE TRN_COMPANY_INFO WHERE PERSON_NAME MATCHES WITH THE CURRENT
            strSQL = @"UPDATE TRN_COMPANY_INFO 
                                   SET    P_PAN       ='" + cmnService.J_ReplaceQuote(txtRPPAN.Text) + @"' 
                                   WHERE  COMPANY_ID  = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)) + @"
                                   AND    PERSON_NAME ='" + cmnService.J_ReplaceQuote(txtResponsiblePersonName.Text.Trim()) + @"' 
                                   AND    UPDATE_FLAG = 0";
            dmlService.J_ExecSql(strSQL);
        }
        #endregion

        #region J_ReturnServerDate
        public string J_ReturnServerDate()
        {
            if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                strSQL = "SELECT CONVERT(CHAR(10),GETDATE(),103)";
            else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                strSQL = "SELECT FORMAT(DATE(),'dd/MM/yyyy')";
            else
                strSQL = "SELECT CONVERT(CHAR(10),GETDATE(),103)";
            //--
            return cmnService.J_NullToText(dmlService.J_ExecSqlReturnScalar(strSQL));
        }






        #endregion

        #endregion


        #region btnVerifyCertificateNo_Click
        private void btnVerifyCertificateNo_Click(object sender, EventArgs e)
        {
            if (txtDeducteePAN.Text.Trim() == "")
            {
                cmnService.J_UserMessage("Enter the PAN to verify the Certificate No.");
                txtDeducteePAN.Select();
                return;
            }
            //
            if (txtCertificateNo.Text.Trim() == "")
            {
                cmnService.J_UserMessage("Enter the Certificate No. for verification.");
                txtCertificateNo.Select();
                return;
            }
            //--
            cmnService.J_ShowChildForm(new TrnCertificate197(txtCertificateNo.Text, txtDeducteePAN.Text, cmbFinancialYear.Text), J_Var.frmMain, "Validate 197 Certificate");
        }
        #endregion

