        #region dgvShowErrFile_CellClick
        private void dgvShowErrFile_CellClick(object sender, DataGridViewCellEventArgs e)
        {
            if (e.ColumnIndex.ToString() == "9")
            {
                if (Convert.ToString(dgvShowErrFile.Rows[dgvShowErrFile.CurrentRow.Index].Cells[2].Value) == "CHALLAN")
                {
                    //--
                    long lngChallanID = 0;
                    strSQL = @"SELECT CHALLAN_ID FROM TRN_CHALLAN WHERE BASIC_INFO_ID = " + lngBasicInfoID + " AND SL_NO = " + Convert.ToString(dgvShowErrFile.Rows[dgvShowErrFile.CurrentRow.Index].Cells[5].Value);
                    lngChallanID = Convert.ToInt64(dmlService.J_ExecSqlReturnScalar(strSQL));
                    //--
                    TrnViewCDErr TrnViewCDErr = new TrnViewCDErr(lngBasicInfoID, lngChallanID, Convert.ToString(dgvShowErrFile.Rows[dgvShowErrFile.CurrentRow.Index].Cells[4].Value));
                    TrnViewCDErr.ShowDialog();
                }
                else if (Convert.ToString(dgvShowErrFile.Rows[dgvShowErrFile.CurrentRow.Index].Cells[2].Value) == "DEDUCTEE")
                {
                    //--
                    long lngDeducteeID = 0;
                    strSQL = @"SELECT DEDUCTEE_DETAIL_ID FROM TRN_DEDUCTEE_DETAILS WHERE BASIC_INFO_ID = " + lngBasicInfoID + " AND SL_NO = " + Convert.ToString(dgvShowErrFile.Rows[dgvShowErrFile.CurrentRow.Index].Cells[6].Value);
                    lngDeducteeID = Convert.ToInt64(dmlService.J_ExecSqlReturnScalar(strSQL));
                    //--
                    TrnViewDDErr TrnViewDDErr = new TrnViewDDErr(lngBasicInfoID, lngDeducteeID, strFormNo, Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex), Convert.ToString(dgvShowErrFile.Rows[dgvShowErrFile.CurrentRow.Index].Cells[4].Value));
                    TrnViewDDErr.ShowDialog();
                }
                else if (Convert.ToString(dgvShowErrFile.Rows[dgvShowErrFile.CurrentRow.Index].Cells[2].Value) == "BATCH")
                {
                    //--
                    //long lngDeducteeID = 0;
                    //strSQL = @"SELECT DEDUCTEE_DETAIL_ID FROM TRN_DEDUCTEE_DETAILS WHERE BASIC_INFO_ID = " + lngBasicInfoID + " AND SL_NO = " + Convert.ToString(dgvShowErrFile.Rows[dgvShowErrFile.CurrentRow.Index].Cells[5].Value);
                    //lngDeducteeID = Convert.ToInt64(dmlService.J_ExecSqlReturnScalar(strSQL));
                    //--
                    TrnViewBHErr TrnViewBHErr = new TrnViewBHErr(Convert.ToInt64(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)), Convert.ToString(dgvShowErrFile.Rows[dgvShowErrFile.CurrentRow.Index].Cells[4].Value));
                    TrnViewBHErr.ShowDialog();
                }
                else if (Convert.ToString(dgvShowErrFile.Rows[dgvShowErrFile.CurrentRow.Index].Cells[2].Value) == "SALARY DETAIL")
                {
                    long lngSalaryID = 0;
                    strSQL = @"SELECT SALARY_DETAILS_ID FROM TRN_SALARY_DETAILS WHERE BASIC_INFO_ID = " + lngBasicInfoID + " AND SL_NO = " + Convert.ToString(dgvShowErrFile.Rows[dgvShowErrFile.CurrentRow.Index].Cells[6].Value);
                    lngSalaryID = Convert.ToInt64(dmlService.J_ExecSqlReturnScalar(strSQL));
                    //--
                    TrnViewSDErr TrnViewSDErr = new TrnViewSDErr(lngBasicInfoID, lngSalaryID, Convert.ToString(dgvShowErrFile.Rows[dgvShowErrFile.CurrentRow.Index].Cells[4].Value));
                    TrnViewSDErr.ShowDialog();
                }
            }
        }
