        #region mnuExport_Click
        private void mnuExport_Click(object sender, EventArgs e)
        {
            string strCSVPath = "";
            try
            {
                // Create a new instance of FolderBrowserDialog.
                FolderBrowserDialog folderBrowserDlg = new FolderBrowserDialog();
                // A new folder button will display in FolderBrowserDialog.
                folderBrowserDlg.ShowNewFolderButton = true;
                //Show FolderBrowserDialog
                DialogResult dlgResult = folderBrowserDlg.ShowDialog();
                if (dlgResult.Equals(DialogResult.OK))
                {
                    //Show selected folder path in textbox1.
                    strCSVPath = folderBrowserDlg.SelectedPath;
                    //Browsing start from root folder.
                    Environment.SpecialFolder rootFolder = folderBrowserDlg.RootFolder;
                }
                //
                if (strCSVPath == "") return;
                //
                strCSVPath = Path.Combine(strCSVPath, System.DateTime.Now.ToString("yyyyMMddHHmmss") + ".csv");
                //
                strSQL = @"SELECT HTML_ERR_FILE_ID AS [SERIAL NO], 
                                LINE_NO            AS [LINE NO],
                                RECORD_TYPE        AS [RECORD TYPE],
                                STATEMENT_TYPE     AS [STATEMENT TYPE],
                                FIELD_NAME         AS [FIELD NAME],
                                CHALLAN_DETAILS_RECORD_NUMBER AS [CD NO],
                                DEDUCTEE_SALARY_94P_DETAIL_NO AS [DD/SD NO],
                                ERROR_DESCRIPTION  AS [ERROR DESCRIPTION]
                        FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_HTML_ERR_FILE;
                ExportToCSV(strSQL, strCSVPath);
                //
                cmnService.J_UserMessage("Export completed");
                //
                System.Diagnostics.Process.Start(strCSVPath);
            }
            catch (Exception err)
            {

            }
        }
        #endregion

