        #region ConvertHTMLTablesToDataTable
        //public static DataTable ConvertHTMLTablesToDataTable(string HTML)
        public void ConvertHTMLTablesToDataTable(string HTML, string TempTable)
        {


            DataTable dt = null;
            DataRow dr = null;
            DataColumn dc = null;
            string TableExpression = "<TABLE[^>]*>(.*?)</TABLE>";
            string HeaderExpression = "<TH[^>]*>(.*?)</TH>";
            string RowExpression = "<TR[^>]*>(.*?)</TR>";
            string ColumnExpression = "<TD[^>]*>(.*?)</TD>";
            bool HeadersExist = false;
            int iCurrentColumn = 0;
            int iCurrentRow = 0;

            // Get a match for all the tables in the HTML    
            MatchCollection Tables = Regex.Matches(HTML, TableExpression, RegexOptions.Multiline | RegexOptions.Singleline | RegexOptions.IgnoreCase);

            // Loop through each table element    
            foreach (Match Table in Tables)
            {

                // Reset the current row counter and the header flag    
                iCurrentRow = 0;
                HeadersExist = false;

                // Add a new table to the DataSet    
                dt = new DataTable();

                // Create the relevant amount of columns for this table (use the headers if they exist, otherwise use default names)    
                if (Table.Value.Contains("<th"))
                {
                    // Set the HeadersExist flag    
                    HeadersExist = true;

                    // Get a match for all the rows in the table    
                    MatchCollection Headers = Regex.Matches(Table.Value, HeaderExpression, RegexOptions.Multiline | RegexOptions.Singleline | RegexOptions.IgnoreCase);

                    // Loop through each header element    
                    foreach (Match Header in Headers)
                    {
                        //dt.Columns.Add(Header.Groups(1).ToString);  
                        dt.Columns.Add(Header.Groups[1].ToString());

                    }
                }
                else
                {
                    for (int iColumns = 1; iColumns <= Regex.Matches(Regex.Matches(Regex.Matches(Table.Value, TableExpression, RegexOptions.Multiline | RegexOptions.Singleline | RegexOptions.IgnoreCase)[0].ToString(), RowExpression, RegexOptions.Multiline | RegexOptions.Singleline | RegexOptions.IgnoreCase)[0].ToString(), ColumnExpression, RegexOptions.Multiline | RegexOptions.Singleline | RegexOptions.IgnoreCase).Count; iColumns++)
                    {
                        dt.Columns.Add("Column " + iColumns);
                    }
                }

                // Get a match for all the rows in the table    
                MatchCollection Rows = Regex.Matches(Table.Value, RowExpression, RegexOptions.Multiline | RegexOptions.Singleline | RegexOptions.IgnoreCase);

                // Loop through each row element    
                foreach (Match Row in Rows)
                {

                    // Only loop through the row if it isn't a header row    
                    if (!(iCurrentRow == 0 & HeadersExist == true))
                    {

                        // Create a new row and reset the current column counter    
                        dr = dt.NewRow();
                        iCurrentColumn = 0;

                        // Get a match for all the columns in the row    
                        MatchCollection Columns = Regex.Matches(Row.Value, ColumnExpression, RegexOptions.Multiline | RegexOptions.Singleline | RegexOptions.IgnoreCase);

                        // Loop through each column element    
                        foreach (Match Column in Columns)
                        {

                            DataColumnCollection columns = dt.Columns;

                            if (!columns.Contains("Column " + iCurrentColumn))
                            {
                                //Add Columns  
                                dt.Columns.Add("Column " + iCurrentColumn);
                            }
                            // Add the value to the DataRow    
                            dr[iCurrentColumn] = Column.Groups[1].ToString();
                            // Increase the current column    
                            iCurrentColumn += 1;

                        }

                        // Add the DataRow to the DataTable    
                        dt.Rows.Add(dr);

                    }

                    // Increase the current row counter    
                    iCurrentRow += 1;
                }


            }

            //return (dt);
            string strLINE_NO = "", strRECORD_TYPE = "", strSTATEMENT_TYPE = "", strFIELD_NAME = "", strCHALLAN_DETAILS_RECORD_NUMBER = "", strDEDUCTEE_SALARY_94P_DETAIL_NO = "", strERROR_CODE_DESCRIPTION = "";
            int i = 0, j = 0;
            foreach (DataRow dataRow in dt.Rows)
            {
                j = 0;
                foreach (object item in dataRow.ItemArray)
                {
                    if (i != 0)
                    {
                        if (j == 0)
                            strLINE_NO = item.ToString();
                        else if (j == 1)
                            strRECORD_TYPE = item.ToString();
                        else if (j == 2)
                            strSTATEMENT_TYPE = item.ToString();
                        else if (j == 3)
                            strFIELD_NAME = item.ToString();
                        else if (j == 4)
                            strCHALLAN_DETAILS_RECORD_NUMBER = item.ToString();
                        else if (j == 5)
                            strDEDUCTEE_SALARY_94P_DETAIL_NO = item.ToString();
                        else if (j == 6)
                            strERROR_CODE_DESCRIPTION = item.ToString();
                        //--
                        j++;
                    }
                    //
                    if (j > 6)
                    {
                        j = 0;
                        strSQL = "INSERT INTO " + TempTable + "(LINE_NO," +
                                "                         RECORD_TYPE," +
                                "                         STATEMENT_TYPE," +
                                "                         FIELD_NAME," +
                                "                         CHALLAN_DETAILS_RECORD_NUMBER," +
                                "                         DEDUCTEE_SALARY_94P_DETAIL_NO," +
                                "                         ERROR_CODE," +
                                "                         ERROR_DESCRIPTION) " +
                                "VALUES                  ('" + cmnService.J_ReplaceQuote(strLINE_NO.Trim().ToUpper()) + "'," +
                                "                         '" + cmnService.J_ReplaceQuote(strRECORD_TYPE.Trim().ToUpper()) + "'," +
                                "                         '" + cmnService.J_ReplaceQuote(strSTATEMENT_TYPE.Trim().ToUpper()) + "'," +
                                "                         '" + cmnService.J_ReplaceQuote(strFIELD_NAME.Trim().ToUpper()) + "'," +
                                "                         '" + cmnService.J_ReplaceQuote(strCHALLAN_DETAILS_RECORD_NUMBER.Trim().ToUpper()) + "'," +
                                "                         '" + cmnService.J_ReplaceQuote(strDEDUCTEE_SALARY_94P_DETAIL_NO.Trim().ToUpper()) + "'," +
                                "                         '" + cmnService.J_ReplaceQuote(cmnService.J_Left(strERROR_CODE_DESCRIPTION.Trim().ToUpper(), 10)) + "'," +
                                "                         '" + cmnService.J_ReplaceQuote(cmnService.J_Right(strERROR_CODE_DESCRIPTION.Trim().ToUpper(), strERROR_CODE_DESCRIPTION.Length - 11).Trim()) + "')";
                        dmlService.J_BeginTransaction();
                        dmlService.J_ExecSql(strSQL);
                        dmlService.J_Commit();
                    }
                }
                i++;
                //
            }

        }

        #endregion

